-- Approval Chance Predictor
UPDATE templates SET
    name                 = $tpl$Approval Chance Predictor$tpl$,
    description          = $tpl$Get a realistic percentage chance of approval before you submit a verification application, based on the same details reviewers use to reject applications. Built for businesses applying for verification and for agencies managing many client applications at once.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"form_details","data":{"icon":"FileText","type":"form","label":"Application Details Form","config":{"fields":[{"key":"businessName","type":"text","label":"Business Name","required":true},{"key":"address","type":"text","label":"Business Address","required":true},{"key":"website","type":"url","label":"Website URL","required":true},{"key":"contactEmail","type":"email","label":"Contact Email","required":true},{"key":"documents","type":"file","label":"Supporting Documents","required":false}],"formTitle":"Approval Chance Check","submitButtonText":"Predict My Chances"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects the exact details a verification reviewer checks, so the prediction is based on the same inputs a real reviewer would see."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_lookup_readiness","data":{"icon":"Database","type":"airtable","label":"Lookup Existing Readiness Record","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"{Email}='{{input.contactEmail}}'","maxRecords":1},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Pulls this client's existing readiness record so the prediction builds on the earlier Readiness Checker result instead of starting from nothing. Filtered to one client — without the filter the AI would receive every client in your table."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_predict_chance","data":{"icon":"Brain","type":"openai_gpt","label":"Compare Against Rejection Reasons","config":{"model":"gpt-4o-mini","prompt":"Compare this business against the most common reasons Meta/Google verification applications get rejected (mismatched business details, missing privacy policy, unverifiable address, inconsistent documents). Business: {{input.businessName}}, address {{input.address}}, website {{input.website}}. Existing readiness data: {{input.records}}. List every risk factor found, one per line starting with \"RISK:\".","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Compares the business against the reasons applications actually get rejected. It outputs one 'RISK:' line per problem found, which the next step counts."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_percentage","data":{"icon":"Code","type":"javascript","label":"Convert to Approval Percentage","config":{"code":"const text = input.response || input.text || '';\nconst risks = text.split('\\n').map(l => l.trim()).filter(l => l.toUpperCase().startsWith('RISK:'));\nconst percentage = Math.max(5, 95 - risks.length * 12);\nreturn { ...input, approvalPercentage: percentage, risks };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the AI's risk lines into a single number a client understands. Each risk costs 12 points off a 95% base — change those numbers here to make the estimate stricter or softer."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"airtable_save_prediction","data":{"icon":"Database","type":"airtable","label":"Save Prediction","config":{"baseId":"","fields":{"Risks":"{{input.risks}}","ApprovalChance":"{{input.approvalPercentage}}"},"tableId":"Clients","recordId":"{{input.records.0.id}}","operation":"update"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Writes the score back onto the same client row so the prediction is on file next time anyone opens the record."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"slack_notify_team","data":{"icon":"MessageCircle","type":"slack_message","label":"Notify Verification Team","config":{"channel":"#verifications","message":":bar_chart: Approval prediction for *{{input.businessName}}*: {{input.approvalPercentage}}% likely to pass.\nRisks: {{input.risks}}"},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Gives your verification team a heads-up on weak applications before the client chases them."}},"type":"custom","position":{"x":1700,"y":205}},{"id":"gmail_send_prediction","data":{"icon":"Mail","type":"google_gmail","label":"Email Client the Result","config":{"body":"Hi {{input.businessName}},\n\nBased on your current details, we estimate a {{input.approvalPercentage}}% chance of passing verification on your next attempt.\n\nWe will follow up with next steps shortly.","subject":"Your estimated approval chance: {{input.approvalPercentage}}%","operation":"send","recipientEmails":"{{input.contactEmail}}","recipientSource":"manual_entry"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the client their number. This is the deliverable — everything above exists to make this email accurate."}},"type":"custom","position":{"x":1700,"y":395}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"form_details","target":"airtable_lookup_readiness"},{"id":"e2","source":"airtable_lookup_readiness","target":"ai_predict_chance"},{"id":"e3","source":"ai_predict_chance","target":"js_percentage"},{"id":"e4","source":"js_percentage","target":"airtable_save_prediction"},{"id":"e5","source":"airtable_save_prediction","target":"slack_notify_team"},{"id":"e6","source":"airtable_save_prediction","target":"gmail_send_prediction"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 21,
    tags                 = ARRAY[$tpl$verification$tpl$,$tpl$compliance$tpl$,$tpl$ai$tpl$,$tpl$airtable$tpl$,$tpl$slack$tpl$,$tpl$prediction$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$ea499f25-1616-40d7-9d64-8f827805e79e$tpl$;

-- Business Details Matcher
UPDATE templates SET
    name                 = $tpl$Business Details Matcher$tpl$,
    description          = $tpl$Catches the silent rejection cause: a business name or address that's written slightly differently on the website vs. the GST filing vs. the bank account. Checks every client every 15 minutes, cross-references every version of the business identity, and emails a match/mismatch report. (No instant Airtable-update trigger exists yet, so this polls every 15 minutes and checks one client per run, marking each as checked so it is never re-reported.)$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"schedule_poll_clients","data":{"icon":"Clock","type":"schedule","label":"Poll for Doc-Complete Clients","config":{"cron":"*/15 * * * *","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs the check on a timer because the platform has no 'Airtable row changed' trigger yet. Each run handles one client, so a 15-minute cycle clears a normal queue easily."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_ready_clients","data":{"icon":"Database","type":"airtable","label":"Read Clients With All Docs","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"AND({Status}='DocsComplete', {MatchCheckedAt}='')","maxRecords":1,"sort":[{"field":"Name","direction":"asc"}]},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Picks up one client whose documents are complete and who has not been checked yet. The MatchCheckedAt filter is what stops the same client being re-reported forever."}},"type":"custom","position":{"x":420,"y":300}},{"id":"js_detect_newly_ready","data":{"icon":"Code","type":"javascript","label":"Select Client to Check","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasClient: false };\nconst f = rec.fields || {};\nreturn {\n  ...input,\n  hasClient: true,\n  recordId: rec.id,\n  businessName: f.Name || \"\",\n  website: f.Website || \"\",\n  contactEmail: f.Email || \"\"\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Lifts the selected client's name, website and email to the top level so the steps below can reference them directly."}},"type":"custom","position":{"x":740,"y":300}},{"id":"http_fetch_website_details","data":{"icon":"Globe","type":"http_request","label":"Fetch Website Business Details","config":{"url":"{{input.website}}","method":"GET","headers":{},"timeout":10000},"category":"http_api","notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Fetches the live website so the AI can read the business details as they are published today, not as they were when the client signed up."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"ai_extract_details","data":{"icon":"Brain","type":"openai_gpt","label":"Extract Name/Address/Phone","config":{"model":"gpt-4o-mini","prompt":"Extract the business name, address and phone number as they appear on this website HTML: {{input.body}}. Then extract the same three fields from the client's uploaded documents. Reply ONLY with JSON in this exact shape: {\"website\":{\"name\":\"\",\"address\":\"\",\"phone\":\"\"},\"gst\":{\"name\":\"\",\"address\":\"\",\"phone\":\"\"},\"pan\":{\"name\":\"\",\"address\":\"\",\"phone\":\"\"},\"bank\":{\"name\":\"\",\"address\":\"\",\"phone\":\"\"}}. Use an empty string where a value is not present.","temperature":0.2},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Reads the name, address and phone out of the website and each document, and returns them as JSON so the comparison below can be exact rather than a guess."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"js_compare_versions","data":{"icon":"Code","type":"javascript","label":"Compare All Versions","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || input.content || \"{}\";\n  const m = text.match(/\\{[\\s\\S]*\\}/);\n  parsed = m ? JSON.parse(m[0]) : {};\n} catch (e) { parsed = {}; }\nconst sources = Object.keys(parsed);\nconst mismatches = [];\nfor (const field of [\"name\", \"address\", \"phone\"]) {\n  const values = sources\n    .map(s => ({ source: s, value: (parsed[s] && parsed[s][field] || \"\").trim().toLowerCase() }))\n    .filter(v => v.value);\n  const distinct = [...new Set(values.map(v => v.value))];\n  if (distinct.length > 1) {\n    mismatches.push(field + \": \" + values.map(v => v.source + \"=\" + v.value).join(\" | \"));\n  }\n}\nreturn { ...input, mismatches, isMatch: mismatches.length === 0 };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Compares every source field by field. This is where a mismatch is actually detected — the AI only extracts, it does not judge."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"airtable_write_match_results","data":{"icon":"Database","type":"airtable","label":"Write Match Results","config":{"baseId":"","fields":{"Mismatches":"{{input.mismatches}}","MatchStatus":"{{input.isMatch}}"},"tableId":"Clients","recordId":"{{input.recordId}}","operation":"update"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Records what matched and what did not, so the mismatch history lives on the client record rather than only in an email."}},"type":"custom","position":{"x":2660,"y":300}},{"id":"gmail_send_match_report","data":{"icon":"Mail","type":"google_gmail","label":"Email Match Report","config":{"body":"Here's what matches and what doesn't across your website, GST, PAN, and bank statement:\n\n{{input.mismatches}}","subject":"Business details check for {{input.businessName}}","operation":"send","recipientEmails":"{{input.contactEmail}}","recipientSource":"manual_entry"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Tells the client exactly which detail is inconsistent and where — the specific thing that gets applications silently rejected."}},"type":"custom","position":{"x":3300,"y":300}},{"id":"airtable_mark_checked","type":"custom","position":{"x":2980,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Client as Checked","category":"data","config":{"baseId":"","tableId":"Clients","operation":"update","recordId":"{{input.recordId}}","fields":{"MatchCheckedAt":"{{input.checkedAt}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Stamps the client as checked. Delete this node and the same client is re-checked and re-emailed every 15 minutes, forever."}}},{"id":"js_stamp_checked","type":"custom","position":{"x":2340,"y":300},"data":{"icon":"Code","type":"javascript","label":"Stamp Check Time","category":"data","config":{"code":"return { ...input, checkedAt: new Date().toISOString() };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Supplies the timestamp for the marker below. Needed because the platform has no {{$now}} built-in."}}},{"id":"if_hasclient","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Any Client to Check?","category":"logic","config":{"conditions":[{"field":"$json.hasClient","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Most polls find nothing. Without this gate the workflow would fetch a blank URL and email an empty report every 15 minutes."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_poll_clients","target":"airtable_read_ready_clients"},{"id":"e2","source":"airtable_read_ready_clients","target":"js_detect_newly_ready"},{"id":"e3","source":"if_hasclient","target":"http_fetch_website_details","sourceHandle":"true"},{"id":"e4","source":"http_fetch_website_details","target":"ai_extract_details"},{"id":"e5","source":"ai_extract_details","target":"js_compare_versions"},{"id":"e6","source":"js_compare_versions","target":"js_stamp_checked"},{"id":"e7","source":"airtable_write_match_results","target":"airtable_mark_checked"},{"id":"e_airtable_mark_checked_gmail_send_match_report","source":"airtable_mark_checked","target":"gmail_send_match_report"},{"id":"e_js_stamp_checked_airtable_write_match_results","source":"js_stamp_checked","target":"airtable_write_match_results"},{"id":"e_js_detect_newly_ready_if_hasclient","source":"js_detect_newly_ready","target":"if_hasclient"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 24,
    tags                 = ARRAY[$tpl$verification$tpl$,$tpl$compliance$tpl$,$tpl$ai$tpl$,$tpl$airtable$tpl$,$tpl$data-matching$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$47f2cdd4-2ccd-43e6-915b-4a2a5b184293$tpl$;

-- Client Priority Ranker
UPDATE templates SET
    name                 = $tpl$Client Priority Ranker$tpl$,
    description          = $tpl$With limited account-management time, this workflow runs every week, reviews every client’s history of delays and issues, estimates who is likely to need help, and sends your team a ranked list so attention goes to the accounts that need it most.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"schedule_weekly_rank","data":{"icon":"Clock","type":"schedule","label":"Run Weekly","config":{"cron":"0 9 * * 1","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Weekly is deliberate: this ranking is for planning the week's account-management time, not for reacting to events."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_client_history","data":{"icon":"Database","type":"airtable","label":"Read Every Client's History","config":{"baseId":"","tableId":"Clients","operation":"read","maxRecords":200},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Reads every client's delay and issue history — the ranking needs the whole set to rank them against each other. Capped at 200 rows so a large table cannot overflow the prompt."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_estimate_outcomes","data":{"icon":"Brain","type":"openai_gpt","label":"Estimate Success Likelihood","config":{"model":"gpt-4o-mini","prompt":"For each client in this list: {{input.records}}, estimate how likely they are to succeed vs. need help, based on their delay history, issue count, and past outcomes. For each client, output a line: \"ClientName | needsHelp: true/false | priority: 1-10\".","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Judges which clients are drifting, using patterns a fixed rule would miss. Output format is one line per client so the next step can sort it."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_sort_by_priority","data":{"icon":"Code","type":"javascript","label":"Sort by Priority","config":{"code":"const text = input.response || input.text || input.content || \"\";\nconst ranked = text.split(\"\\n\")\n  .filter(l => l.includes(\"|\"))\n  .map(l => {\n    const parts = l.split(\"|\").map(p => p.trim());\n    const priorityPart = parts.find(p => p.toLowerCase().startsWith(\"priority\"));\n    const priority = priorityPart ? parseInt(priorityPart.split(\":\")[1], 10) : 5;\n    return { client: parts[0], line: l, priority: isNaN(priority) ? 5 : priority };\n  })\n  .sort((a, b) => b.priority - a.priority);\n// Slack renders a string, not an object array.\nconst rankedText = ranked.map((r, i) => (i + 1) + \". \" + r.client + \"  (priority \" + r.priority + \")\").join(\"\\n\");\nreturn { ...input, ranked, rankedText, rankedCount: ranked.length };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Sorts the AI's lines into a ranked list and formats it as text. Slack renders raw objects as unreadable JSON, so the formatting matters."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"slack_send_ranked_list","data":{"icon":"MessageCircle","type":"slack_message","label":"Send Ranked List to Team","config":{"channel":"#account-management","message":":clipboard: This week's client priority ranking ({{input.rankedCount}} clients, highest first):\n{{input.rankedText}}"},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the ranked list where the team already works. This is the whole output of the workflow."}},"type":"custom","position":{"x":1380,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_weekly_rank","target":"airtable_read_client_history"},{"id":"e2","source":"airtable_read_client_history","target":"ai_estimate_outcomes"},{"id":"e3","source":"ai_estimate_outcomes","target":"js_sort_by_priority"},{"id":"e4","source":"js_sort_by_priority","target":"slack_send_ranked_list"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$account-management$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$,$tpl$prioritization$tpl$,$tpl$airtable$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$ca1c8a37-6786-4dce-a785-a3288283e794$tpl$;

