-- CRM Data Cleanup Assistant (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000014$tpl$, $tpl$CRM Data Cleanup Assistant$tpl$, $tpl$Find one CRM contact needing cleanup, detect missing fields, update the CRM, and notify ops when human research is needed.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"schedule_crm_cleanup","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check CRM Records","category":"triggers","config":{"cron":"*/20 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs continuously but lightly, cleaning one record per pass."}}},{"id":"hubspot_read_contact","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"hubspot","label":"Find Contact to Clean","category":"crm","config":{"resource":"contact","operation":"list","properties":{"limit":1}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Uses the real CRM node so the template works against the system sales teams use."}}},{"id":"js_detect_missing_crm","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Detect Missing Fields","category":"data","config":{"code":"const contact = (input.results || input.contacts || [])[0] || input;\nconst missing = [\"email\", \"firstname\", \"company\"].filter((field) => !contact[field]);\nreturn { ...input, contactId: contact.id || \"\", missing, needsResearch: missing.length > 0, missingText: missing.join(\", \") || \"None\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Finds the exact fields missing from the contact record."}}},{"id":"if_crm_missing","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Cleanup?","category":"logic","config":{"conditions":[{"field":"$json.needsResearch","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only records with missing required fields create work for ops."}}},{"id":"slack_crm_research","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Ask Ops to Research","category":"output","config":{"channel":"#revops","message":"CRM contact needs cleanup. Missing: {{input.missingText}}. Contact ID: {{input.contactId}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes incomplete records to RevOps for human research."}}},{"id":"hubspot_mark_reviewed","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Box","type":"hubspot","label":"Mark Reviewed","category":"crm","config":{"resource":"contact","operation":"update","id":"{{input.contactId}}","properties":{"ctrlchecks_reviewed":"true"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Marks the contact as reviewed so it can be excluded from future cleanup passes."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_crm_cleanup_hubspot_read_contact","source":"schedule_crm_cleanup","target":"hubspot_read_contact"},{"id":"e_2_hubspot_read_contact_js_detect_missing_crm","source":"hubspot_read_contact","target":"js_detect_missing_crm"},{"id":"e_3_js_detect_missing_crm_if_crm_missing","source":"js_detect_missing_crm","target":"if_crm_missing"},{"id":"e_4_if_crm_missing_slack_crm_research","source":"if_crm_missing","target":"slack_crm_research","sourceHandle":"true"},{"id":"e_5_if_crm_missing_hubspot_mark_reviewed","source":"if_crm_missing","target":"hubspot_mark_reviewed","sourceHandle":"false"},{"id":"e_6_slack_crm_research_hubspot_mark_reviewed","source":"slack_crm_research","target":"hubspot_mark_reviewed"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  23, ARRAY[$tpl$crm$tpl$,$tpl$hubspot$tpl$,$tpl$cleanup$tpl$,$tpl$operations$tpl$,$tpl$slack$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$CRM Data Cleanup Assistant$tpl$,
    description          = $tpl$Find one CRM contact needing cleanup, detect missing fields, update the CRM, and notify ops when human research is needed.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"schedule_crm_cleanup","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check CRM Records","category":"triggers","config":{"cron":"*/20 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs continuously but lightly, cleaning one record per pass."}}},{"id":"hubspot_read_contact","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"hubspot","label":"Find Contact to Clean","category":"crm","config":{"resource":"contact","operation":"list","properties":{"limit":1}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Uses the real CRM node so the template works against the system sales teams use."}}},{"id":"js_detect_missing_crm","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Detect Missing Fields","category":"data","config":{"code":"const contact = (input.results || input.contacts || [])[0] || input;\nconst missing = [\"email\", \"firstname\", \"company\"].filter((field) => !contact[field]);\nreturn { ...input, contactId: contact.id || \"\", missing, needsResearch: missing.length > 0, missingText: missing.join(\", \") || \"None\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Finds the exact fields missing from the contact record."}}},{"id":"if_crm_missing","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Cleanup?","category":"logic","config":{"conditions":[{"field":"$json.needsResearch","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only records with missing required fields create work for ops."}}},{"id":"slack_crm_research","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Ask Ops to Research","category":"output","config":{"channel":"#revops","message":"CRM contact needs cleanup. Missing: {{input.missingText}}. Contact ID: {{input.contactId}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes incomplete records to RevOps for human research."}}},{"id":"hubspot_mark_reviewed","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Box","type":"hubspot","label":"Mark Reviewed","category":"crm","config":{"resource":"contact","operation":"update","id":"{{input.contactId}}","properties":{"ctrlchecks_reviewed":"true"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Marks the contact as reviewed so it can be excluded from future cleanup passes."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_schedule_crm_cleanup_hubspot_read_contact","source":"schedule_crm_cleanup","target":"hubspot_read_contact"},{"id":"e_2_hubspot_read_contact_js_detect_missing_crm","source":"hubspot_read_contact","target":"js_detect_missing_crm"},{"id":"e_3_js_detect_missing_crm_if_crm_missing","source":"js_detect_missing_crm","target":"if_crm_missing"},{"id":"e_4_if_crm_missing_slack_crm_research","source":"if_crm_missing","target":"slack_crm_research","sourceHandle":"true"},{"id":"e_5_if_crm_missing_hubspot_mark_reviewed","source":"if_crm_missing","target":"hubspot_mark_reviewed","sourceHandle":"false"},{"id":"e_6_slack_crm_research_hubspot_mark_reviewed","source":"slack_crm_research","target":"hubspot_mark_reviewed"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 23,
    tags                 = ARRAY[$tpl$crm$tpl$,$tpl$hubspot$tpl$,$tpl$cleanup$tpl$,$tpl$operations$tpl$,$tpl$slack$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Cross-Platform Sync Engine
UPDATE templates SET
    name                 = $tpl$Cross-Platform Sync Engine$tpl$,
    description          = $tpl$Keep client data in Airtable, your CRM and a shared spreadsheet from drifting apart. Every 15 minutes this workflow picks up one client record that has changed since it was last synced, pushes it to HubSpot and Google Sheets, then stamps it as synced so it is never pushed twice. Requires a HubSpotId column on your Airtable table. (No instant Airtable-update trigger exists yet, so this polls.)$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"schedule_poll_changes","data":{"icon":"Clock","type":"schedule","label":"Poll for Client Record Changes","config":{"cron":"*/15 * * * *","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Polls because there is no 'Airtable row changed' trigger. One record per run keeps the sync safe and rate-limit friendly."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_all_clients","data":{"icon":"Database","type":"airtable","label":"Read All Client Records","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"OR({LastSyncedAt}='', IS_AFTER(LAST_MODIFIED_TIME(), {LastSyncedAt}))","maxRecords":1},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Picks up one record modified since it was last synced. The LastSyncedAt filter is the safety mechanism — without it every record looks changed on every run."}},"type":"custom","position":{"x":420,"y":300}},{"id":"js_diff_changed_fields","data":{"icon":"Code","type":"javascript","label":"Select Record to Sync","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasRecord: false };\nconst f = rec.fields || {};\n// HubSpot needs its own contact id; store it on the Airtable row as HubSpotId.\nreturn {\n  ...input,\n  hasRecord: true,\n  recordId: rec.id,\n  hubspotContactId: f.HubSpotId || \"\",\n  diffFields: { firstname: f.Name || \"\", email: f.Email || \"\", website: f.Website || \"\" },\n  sheetRow: [[f.Name || \"\", f.Email || \"\", f.Website || \"\", f.Status || \"\"]],\n  syncedAt: new Date().toISOString()\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Maps the Airtable row onto the shapes HubSpot and Sheets each expect. Your Airtable table needs a HubSpotId column for the CRM push to find the right contact."}},"type":"custom","position":{"x":740,"y":300}},{"id":"hubspot_push_changes","data":{"icon":"Database","type":"hubspot","label":"Push Changed Fields to HubSpot","config":{"id":"{{input.hubspotContactId}}","resource":"contact","operation":"update","properties":"{{input.diffFields}}"},"category":"crm","notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Updates the matching CRM contact. This is a write into your real CRM — test it against a sandbox contact before switching the template on."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"sheets_update_shared_copy","data":{"icon":"Database","type":"google_sheets","label":"Update Shared Spreadsheet","config":{"range":"Clients!A:D","values":"{{input.sheetRow}}","operation":"update","sheetName":"Clients","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID"},"category":"data","notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Keeps the shared spreadsheet in step for people who do not have CRM access."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"slack_log_sync","data":{"icon":"MessageCircle","type":"slack_message","label":"Log Sync Confirmation","config":{"channel":"#data-sync-log","message":":white_check_mark: Synced client record {{input.recordId}} to HubSpot and Google Sheets."},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"A quiet audit trail so you can tell whether a sync ran without opening three systems."}},"type":"custom","position":{"x":2340,"y":300}},{"id":"airtable_mark_synced","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Record Sync Time","category":"data","config":{"baseId":"","tableId":"Clients","operation":"update","recordId":"{{input.recordId}}","fields":{"LastSyncedAt":"{{input.syncedAt}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Stamps the row as synced. This is the single most important node here — remove it and the workflow re-pushes every client to HubSpot and Sheets every 15 minutes indefinitely."}}},{"id":"if_hasrecord","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Anything Changed?","category":"logic","config":{"conditions":[{"field":"$json.hasRecord","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Stops an empty poll from pushing a blank contact into your CRM and a blank row into your spreadsheet."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_poll_changes","target":"airtable_read_all_clients"},{"id":"e2","source":"airtable_read_all_clients","target":"js_diff_changed_fields"},{"id":"e3","source":"if_hasrecord","target":"hubspot_push_changes","sourceHandle":"true"},{"id":"e4","source":"hubspot_push_changes","target":"sheets_update_shared_copy"},{"id":"e5","source":"sheets_update_shared_copy","target":"airtable_mark_synced"},{"id":"e_airtable_mark_synced_slack_log_sync","source":"airtable_mark_synced","target":"slack_log_sync"},{"id":"e_js_diff_changed_fields_if_hasrecord","source":"js_diff_changed_fields","target":"if_hasrecord"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 18,
    tags                 = ARRAY[$tpl$sync$tpl$,$tpl$hubspot$tpl$,$tpl$google-sheets$tpl$,$tpl$airtable$tpl$,$tpl$crm$tpl$,$tpl$automation$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$85e90794-5759-4cda-9738-6c045e5e1c6c$tpl$;

-- Customer Churn Risk Alert (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000015$tpl$, $tpl$Customer Churn Risk Alert$tpl$, $tpl$Poll one customer account, score churn risk from usage and notes, alert account managers, and mark the record checked.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"schedule_churn_check","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check Customer Risk","category":"triggers","config":{"cron":"*/30 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs on a timer because churn signals appear in account data over time."}}},{"id":"airtable_read_customer","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One Customer","category":"data","config":{"baseId":"","tableId":"Customers","operation":"read","filterByFormula":"AND({Status}='Active', {ChurnCheckedAt}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Selects one active customer that has not been checked yet."}}},{"id":"ai_churn_score","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Score Churn Risk","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Score churn risk for this customer record: {{input.records}}. Return ONLY JSON: {\"risk\":\"low|medium|high\",\"reason\":\"short reason\",\"nextAction\":\"specific action\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Uses account context to judge risk and recommend the next action."}}},{"id":"js_parse_churn","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Risk Score","category":"data","config":{"code":"const rec = (input.records || [])[0];\nlet parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nconst f = rec?.fields || {};\nreturn { ...input, recordId: rec?.id || \"\", customerName: f.Name || \"customer\", ownerChannel: f.OwnerChannel || \"#customer-success\", risk: parsed.risk || \"medium\", reason: parsed.reason || \"\", nextAction: parsed.nextAction || \"\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Combines the Airtable record ID with the parsed AI risk fields."}}},{"id":"if_high_churn","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"High Churn Risk?","category":"logic","config":{"conditions":[{"field":"$json.risk","operator":"equals","value":"high"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only high-risk accounts interrupt the account team."}}},{"id":"slack_churn_alert","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Account Manager","category":"output","config":{"channel":"{{input.ownerChannel}}","message":"High churn risk: {{input.customerName}}\nReason: {{input.reason}}\nNext action: {{input.nextAction}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes the alert to the owner responsible for saving the account."}}},{"id":"airtable_mark_churn_checked","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Checked","category":"data","config":{"baseId":"","tableId":"Customers","operation":"update","recordId":"{{input.recordId}}","fields":{"ChurnCheckedAt":"Checked"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Prevents the same customer from being rescored on every poll."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_churn_check_airtable_read_customer","source":"schedule_churn_check","target":"airtable_read_customer"},{"id":"e_2_airtable_read_customer_ai_churn_score","source":"airtable_read_customer","target":"ai_churn_score"},{"id":"e_3_ai_churn_score_js_parse_churn","source":"ai_churn_score","target":"js_parse_churn"},{"id":"e_4_js_parse_churn_if_high_churn","source":"js_parse_churn","target":"if_high_churn"},{"id":"e_5_if_high_churn_slack_churn_alert","source":"if_high_churn","target":"slack_churn_alert","sourceHandle":"true"},{"id":"e_6_if_high_churn_airtable_mark_churn_checked","source":"if_high_churn","target":"airtable_mark_churn_checked","sourceHandle":"false"},{"id":"e_7_slack_churn_alert_airtable_mark_churn_checked","source":"slack_churn_alert","target":"airtable_mark_churn_checked"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  22, ARRAY[$tpl$customer-success$tpl$,$tpl$churn$tpl$,$tpl$airtable$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$]::text[],
