  $tpl$b7f3c1d2-4e58-4a91-9c06-2d8e5f0a7b34$tpl$, $tpl$Document Vault — Smart Search$tpl$, $tpl$Ask for any stored client document in plain English over chat and get the file link back. Reads the tagged vault built by "Document Vault — Intake & Auto-Tagging".$tpl$, $tpl$Business Verification & Compliance$tpl$,
  $tpl$[{"id":"chat_trigger_search","data":{"icon":"MessageSquare","type":"chat_trigger","label":"Search Request","config":{},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Lets anyone ask for a document in plain English instead of digging through folders."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_parse_search_query","data":{"icon":"Code","type":"javascript","label":"Parse Search Terms","config":{"code":"const raw = (typeof input === 'string') ? input : (input && (input.message || input.query || input.text)) || '';\nreturn { ...(typeof input === \"object\" && input ? input : {}), searchQuery: raw };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Takes the raw chat message and prepares it as a search term. Written to work whether the chat trigger hands over a string or an object."}},"type":"custom","position":{"x":420,"y":300}},{"id":"airtable_search_vault","data":{"icon":"Database","type":"airtable","label":"Search Document Vault","config":{"baseId":"","tableId":"DocumentVault","operation":"read","maxRecords":200},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Reads the tagged vault built by the Intake template. Capped so a large vault cannot overflow the agent's prompt."}},"type":"custom","position":{"x":740,"y":300}},{"id":"ai_agent_find_match","data":{"icon":"Bot","type":"ai_agent","label":"Find the Matching File","config":{"model":"gemini-3.5-flash","userInput":"Search query: {{input.searchQuery}}\nAvailable documents: {{input.records}}","temperature":0.2,"systemPrompt":"You are a document vault search assistant. You are given a search query and a list of tagged documents (client, type, date, link). Find the single best match and reply with a short sentence containing its file link. If nothing matches well, say so and suggest what to search instead."},"category":"ai","notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Matches a loose human request ('that PAN card from March') against the tagged records and picks the best one."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"whatsapp_reply_search","data":{"icon":"Send","type":"chat_send","label":"Reply in Chat","config":{"message":"{{input.response}}"},"category":"output","notes":{"family":"Database","what":"Sends a reply in a chat conversation — works with a chat trigger to create a bot","overview":"","tips":[],"docsHref":null,"why":"Returns the matched file link in the same chat where the request was made."}},"type":"custom","position":{"x":1380,"y":300}}]$tpl$::jsonb, $tpl$[{"id":"e3","source":"chat_trigger_search","target":"js_parse_search_query"},{"id":"e4","source":"js_parse_search_query","target":"airtable_search_vault"},{"id":"e5","source":"airtable_search_vault","target":"ai_agent_find_match"},{"id":"e6","source":"ai_agent_find_match","target":"whatsapp_reply_search"}]$tpl$::jsonb, $tpl$Advanced$tpl$,
  12, ARRAY[$tpl$ai-agent$tpl$,$tpl$document-management$tpl$,$tpl$search$tpl$,$tpl$airtable$tpl$,$tpl$chatbot$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
