    nodes                = $tpl$[{"id":"schedule_onboarding","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check New Hires","category":"triggers","config":{"cron":"0 10 * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs daily to pick up new hires without manual HR checks."}}},{"id":"airtable_read_new_hire","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One New Hire","category":"data","config":{"baseId":"","tableId":"NewHires","operation":"read","filterByFormula":"AND({Status}='Ready', {OnboardingStarted}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Selects one ready new hire that has not started onboarding."}}},{"id":"js_prepare_onboarding","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Prepare Onboarding Payload","category":"data","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasHire: false };\nconst f = rec.fields || {};\nreturn { ...input, hasHire: true, recordId: rec.id, employeeName: f.Name || \"there\", employeeEmail: f.Email || \"\", manager: f.Manager || \"your manager\", startDate: f.StartDate || \"\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Lifts new-hire fields into a clean payload for email, Slack and marking."}}},{"id":"if_has_hire","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"New Hire Found?","category":"logic","config":{"conditions":[{"field":"$json.hasHire","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Stops empty daily checks from sending blank onboarding messages."}}},{"id":"gmail_onboarding","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Mail","type":"google_gmail","label":"Email New Hire","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.employeeEmail}}","subject":"Welcome to the team","body":"Hi {{input.employeeName}},\n\nWelcome. Your start date is {{input.startDate}}. Your manager is {{input.manager}}. We will share your onboarding tasks shortly."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends a consistent welcome email to the new hire."}}},{"id":"slack_onboarding","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Notify Hiring Team","category":"output","config":{"channel":"#people-ops","message":"Onboarding started for {{input.employeeName}}. Manager: {{input.manager}}. Start: {{input.startDate}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Tells People Ops and the manager that onboarding has started."}}},{"id":"airtable_mark_onboarding","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Started","category":"data","config":{"baseId":"","tableId":"NewHires","operation":"update","recordId":"{{input.recordId}}","fields":{"OnboardingStarted":"Yes"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Prevents duplicate onboarding starts for the same employee."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_schedule_onboarding_airtable_read_new_hire","source":"schedule_onboarding","target":"airtable_read_new_hire"},{"id":"e_2_airtable_read_new_hire_js_prepare_onboarding","source":"airtable_read_new_hire","target":"js_prepare_onboarding"},{"id":"e_3_js_prepare_onboarding_if_has_hire","source":"js_prepare_onboarding","target":"if_has_hire"},{"id":"e_4_if_has_hire_gmail_onboarding","source":"if_has_hire","target":"gmail_onboarding","sourceHandle":"true"},{"id":"e_5_gmail_onboarding_slack_onboarding","source":"gmail_onboarding","target":"slack_onboarding"},{"id":"e_6_slack_onboarding_airtable_mark_onboarding","source":"slack_onboarding","target":"airtable_mark_onboarding"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 17,
    tags                 = ARRAY[$tpl$hr$tpl$,$tpl$onboarding$tpl$,$tpl$airtable$tpl$,$tpl$email$tpl$,$tpl$slack$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Expense Policy Checker (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000007$tpl$, $tpl$Expense Policy Checker$tpl$, $tpl$Check submitted expenses against policy, save the result, and notify finance only when an expense needs review.$tpl$, $tpl$Finance, Accounting & Insurance$tpl$,
  $tpl$[{"id":"form_expense","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Expense Form","category":"triggers","config":{"fields":[{"key":"employeeEmail","type":"email","label":"Employee Email","required":true},{"key":"amount","type":"number","label":"Amount","required":true},{"key":"category","type":"text","label":"Category","required":true},{"key":"description","type":"textarea","label":"Description","required":true}],"formTitle":"Expense Check","submitButtonText":"Submit Expense"},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Captures the expense data needed for policy review."}}},{"id":"ai_policy_check","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Check Policy Fit","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Check this expense against a normal business expense policy. Amount: {{input.amount}}. Category: {{input.category}}. Description: {{input.description}}. Return ONLY JSON: {\"approved\":true|false,\"reason\":\"short reason\",\"risk\":\"low|medium|high\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Flags unusual expenses while allowing normal ones through."}}},{"id":"js_parse_expense","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Policy Result","category":"data","config":{"code":"let parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nreturn { ...input, approved: parsed.approved === true, reason: parsed.reason || \"\", risk: parsed.risk || \"medium\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the AI result into fields that can be stored and branched on."}}},{"id":"postgres_save_expense","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Box","type":"postgresql","label":"Save Expense Review","category":"data","config":{"query":"INSERT INTO expense_reviews (employee_email, amount, category, approved, risk, reason, created_at) VALUES ('{{input.employeeEmail}}', {{input.amount}}, '{{input.category}}', '{{input.approved}}', '{{input.risk}}', '{{input.reason}}', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Keeps every policy decision auditable."}}},{"id":"if_expense_review","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Finance Review?","category":"logic","config":{"conditions":[{"field":"$json.approved","operator":"equals","value":false}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only sends exceptions to finance; approved expenses are simply recorded."}}},{"id":"slack_expense_review","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Finance","category":"output","config":{"channel":"#finance-review","message":"Expense needs review: {{input.employeeEmail}} / {{input.amount}}\nRisk: {{input.risk}}\nReason: {{input.reason}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Notifies finance when the policy result is not approved."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_expense_ai_policy_check","source":"form_expense","target":"ai_policy_check"},{"id":"e_2_ai_policy_check_js_parse_expense","source":"ai_policy_check","target":"js_parse_expense"},{"id":"e_3_js_parse_expense_postgres_save_expense","source":"js_parse_expense","target":"postgres_save_expense"},{"id":"e_4_postgres_save_expense_if_expense_review","source":"postgres_save_expense","target":"if_expense_review"},{"id":"e_5_if_expense_review_slack_expense_review","source":"if_expense_review","target":"slack_expense_review","sourceHandle":"true"}]$tpl$::jsonb, $tpl$Beginner$tpl$,
  18, ARRAY[$tpl$finance$tpl$,$tpl$expenses$tpl$,$tpl$policy$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
