-- FAQ Answering Assistant
UPDATE templates SET
    name                 = $tpl$FAQ Answering Assistant$tpl$,
    description          = $tpl$Let clients ask their own questions instead of pinging your team every time. This chat assistant answers strictly from your own FAQ records and automatically hands the question to a human in Slack whenever it isn't confident in the answer.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"chat_trigger_faq","data":{"icon":"MessageSquare","type":"chat_trigger","label":"Client Question","config":{},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Lets clients ask their own questions instead of messaging your team."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_faq","data":{"icon":"Database","type":"airtable","label":"Search FAQ Knowledge Base","config":{"baseId":"","tableId":"FAQ","operation":"read","maxRecords":50},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Loads your FAQ records. The AI answers only from these, which is what stops it inventing policy. Capped at 50 rows."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_answer_from_faq","data":{"icon":"Brain","type":"openai_gpt","label":"Answer Using Only FAQ Docs","config":{"model":"gpt-4o-mini","prompt":"You are a support assistant. Using ONLY the information in these FAQ records: {{input.records}}, answer this client question: \"{{input.message}}\". If the FAQ records do not contain a confident answer, say \"I am not fully sure\" and set your confidence low. Respond with a JSON object: {\"answer\": \"...\", \"confidence\": 0.0-1.0}.","temperature":0.2},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Answers strictly from the supplied FAQ records and rates its own confidence, so the workflow can tell a solid answer from a guess."}},"type":"custom","position":{"x":740,"y":300}},{"id":"if_confidence_check","data":{"icon":"GitBranch","type":"if_else","label":"Check AI Confidence","config":{"conditions":[{"field":"$json.confidence","value":0.75,"operator":"greater_than_or_equal"}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Decides whether the client hears from the bot or from a person. 0.75 is the dial — lower it to answer more questions automatically, raise it to be more cautious."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"whatsapp_reply_client","data":{"icon":"Send","type":"chat_send","label":"Reply in Chat","config":{"message":"{{input.answer}}"},"category":"output","notes":{"family":"Database","what":"Sends a reply in a chat conversation — works with a chat trigger to create a bot","overview":"","tips":[],"docsHref":null,"why":"Returns a confident answer in the active chat session."}},"type":"custom","position":{"x":1700,"y":205}},{"id":"slack_escalate_human","data":{"icon":"MessageCircle","type":"slack_message","label":"Escalate to Human","config":{"channel":"#support","message":":warning: Low-confidence AI answer for: \"{{input.message}}\"\nDraft answer: {{input.answer}}\nPlease review and reply directly."},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Hands an uncertain question to your team with the AI's draft attached, so the human starts from something rather than nothing."}},"type":"custom","position":{"x":1700,"y":395}},{"id":"js_parse_faq_answer","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse AI Answer","category":"data","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || input.content || \"{}\";\n  const m = text.match(/\\{[\\s\\S]*\\}/);\n  parsed = m ? JSON.parse(m[0]) : {};\n} catch (e) { parsed = {}; }\nreturn {\n  ...input,\n  answer: parsed.answer || input.response || input.text || \"\",\n  confidence: typeof parsed.confidence === \"number\" ? parsed.confidence : 0\n};","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Extracts the answer and the confidence score from the AI's JSON. Without this the gate below has no confidence value to read and every question escalates."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"chat_trigger_faq","target":"airtable_read_faq"},{"id":"e2","source":"airtable_read_faq","target":"ai_answer_from_faq"},{"id":"e3","source":"ai_answer_from_faq","target":"js_parse_faq_answer"},{"id":"e4","source":"if_confidence_check","target":"whatsapp_reply_client","sourceHandle":"true"},{"id":"e5","source":"if_confidence_check","target":"slack_escalate_human","sourceHandle":"false"},{"id":"e_js_parse_faq_answer_if_confidence_check","source":"js_parse_faq_answer","target":"if_confidence_check"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$support$tpl$,$tpl$ai$tpl$,$tpl$chatbot$tpl$,$tpl$chat$tpl$,$tpl$slack$tpl$,$tpl$faq$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$97432e3a-fb6e-4b90-9364-10fbe77c7371$tpl$;

-- Finance / Compliance Agent
UPDATE templates SET
    name                 = $tpl$Finance / Compliance Agent$tpl$,
    description          = $tpl$Automated finance operations agent that processes invoices and expenses, categorizes transactions, performs compliance checks, and triggers alerts for anomalies. Reduces manual finance workload.$tpl$,
    category             = $tpl$Finance, Accounting & Insurance$tpl$,
    nodes                = $tpl$[{"id":"webhook_finance_1","data":{"icon":"Webhook","type":"webhook","label":"Finance Webhook","config":{"method":"POST"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives transactions from your accounting or expense system. This endpoint is currently open — put a shared secret in front of it before using real financial data."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_extract_transaction","data":{"icon":"Code","type":"javascript","label":"Extract Transaction Data","config":{"code":"return { type: input.type || input.transaction_type || 'expense', amount: parseFloat(input.amount || 0), vendor: input.vendor || input.supplier || '', description: input.description || input.notes || '', date: input.date || input.transaction_date || new Date().toISOString().split('T')[0], category: input.category || '', invoice_number: input.invoice_number || input.invoice_id || '', employee_id: input.employee_id || input.employee || '', receipt_url: input.receipt_url || input.file_url || '', timestamp: new Date().toISOString() };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Normalises the many field names different finance systems use into one shape the rest of the workflow can rely on."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_categorize","data":{"icon":"Brain","type":"openai_gpt","label":"Categorize Transaction","config":{"model":"gpt-4o-mini","memory":3,"prompt":"Categorize this financial transaction. Return JSON: { category: string (one of: Travel, Meals, Software, Hardware, Office Supplies, Marketing, Professional Services, Utilities, Other), confidence: number (0-1), reasoning: string }\\n\\nTransaction: Vendor: {{input.vendor}}, Description: {{input.description}}, Amount: ${{input.amount}}","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Assigns a spend category. Doing this with AI rather than keyword rules is what handles vendors nobody has seen before."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_parse_category","data":{"icon":"Code","type":"javascript","label":"Parse Category","config":{"code":"try { const content = input.content || input.text || input.response || '{}'; const jsonMatch = content.match(/\\{[\\s\\S]*\\}/); if (jsonMatch) { const parsed = JSON.parse(jsonMatch[0]); return { category: parsed.category || 'Other', confidence: parsed.confidence || 0.5, reasoning: parsed.reasoning || 'No reasoning', transaction: input }; } return { category: 'Other', confidence: 0.5, reasoning: 'Could not parse', transaction: input }; } catch (e) { return { category: 'Other', confidence: 0.5, reasoning: 'Error: ' + e.message, transaction: input }; }"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Extracts the category and confidence from the AI's JSON reply."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"js_compliance_check","data":{"icon":"Code","type":"javascript","label":"Compliance Check","config":{"code":"// Change this to your own approval threshold when you set up the template.\nconst approvalThreshold = Number(input.approvalThreshold || 10000);\nconst amount = parseFloat(input.transaction.amount || 0); const category = input.category; const violations = []; if (amount > approvalThreshold) { violations.push({ type: 'high_amount', message: 'Transaction exceeds  }); } if (amount < 0) { violations.push({ type: 'negative_amount', message: 'Negative amount detected - possible refund or error' }); } if (!category || category === 'Other') { violations.push({ type: 'uncategorized', message: 'Transaction is uncategorized - needs review' }); } if (!input.transaction.vendor || input.transaction.vendor.trim() === '') { violations.push({ type: 'missing_vendor', message: 'Missing vendor information' }); } return { compliant: violations.length === 0, violations, transaction: input.transaction, category: input.category, confidence: input.confidence }; + approvalThreshold + ' - requires approval' }); } if (amount < 0) { violations.push({ type: 'negative_amount', message: 'Negative amount detected - possible refund or error' }); } if (!category || category === 'Other') { violations.push({ type: 'uncategorized', message: 'Transaction is uncategorized - needs review' }); } if (!input.transaction.vendor || input.transaction.vendor.trim() === '') { violations.push({ type: 'missing_vendor', message: 'Missing vendor information' }); } return { compliant: violations.length === 0, violations, transaction: input.transaction, category: input.category, confidence: input.confidence };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Applies your actual policy rules — amount ceiling, missing vendor, uncategorised spend. The approval threshold lives here; change it to match your policy."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"if_compliant_check","data":{"icon":"GitBranch","type":"if_else","label":"Check Compliance","config":{"conditions":[{"field":"$json.compliant","operator":"equals","value":true}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Splits clean transactions from ones needing a human. Everything below exists on one side of this decision."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"db_save_transaction","data":{"icon":"Database","type":"postgresql","label":"Save Transaction","config":{"query":"INSERT INTO transactions (type, amount, vendor, description, category, date, invoice_number, employee_id, status, created_at) VALUES ('{{input.transaction.type}}', {{input.transaction.amount}}, '{{input.transaction.vendor}}', '{{input.transaction.description}}', '{{input.category}}', '{{input.transaction.date}}', '{{input.transaction.invoice_number}}', '{{input.transaction.employee_id}}', 'approved', now())"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Records the approved transaction with its category, in your own finance database."}},"type":"custom","position":{"x":2020,"y":205}},{"id":"log_approved","data":{"icon":"FileOutput","type":"log_output","label":"Log Approved","config":{"level":"info","message":"Transaction approved: ${{input.transaction.amount}} - {{input.category}} - {{input.transaction.vendor}}"},"category":"utility","notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"A quiet trail of what passed, for reconciliation."}},"type":"custom","position":{"x":2340,"y":205}},{"id":"db_save_flag","data":{"icon":"Database","type":"postgresql","label":"Flag Transaction for Review","config":{"query":"INSERT INTO transactions (type, amount, vendor, description, category, date, invoice_number, employee_id, status, violations, created_at) VALUES ('{{input.transaction.type}}', {{input.transaction.amount}}, '{{input.transaction.vendor}}', '{{input.transaction.description}}', '{{input.category}}', '{{input.transaction.date}}', '{{input.transaction.invoice_number}}', '{{input.transaction.employee_id}}', 'flagged', '{{input.violationsJson}}', now())"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Saves the flagged transaction with its violations attached, so the review queue is a real queue and not just a Slack message."}},"type":"custom","position":{"x":2020,"y":395}},{"id":"js_format_alert","data":{"icon":"Code","type":"javascript","label":"Format Alert","config":{"code":"const violations = input.violations || []; const violationsText = violations.map(v => `- ${v.type}: ${v.message}`).join('\\n'); const violationsJson = JSON.stringify(violations);\nreturn { violationsJson, alert: `⚠️ Compliance Alert\\n\\nTransaction: $${input.transaction.amount}\\nVendor: ${input.transaction.vendor}\\nCategory: ${input.category}\\n\\nViolations:\\n${violationsText}\\n\\nAction Required: Review and approve manually.`, violations, transaction: input.transaction };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Builds the human-readable alert and the machine-readable violations list used by the step above."}},"type":"custom","position":{"x":2340,"y":395}},{"id":"slack_finance_alert","data":{"icon":"MessageCircle","type":"slack_webhook","label":"Notify Finance Team","config":{"message":"{{input.alert}}","username":"Finance Bot","webhookUrl":"REPLACE_WITH_YOUR_SLACK_INCOMING_WEBHOOK_URL"},"category":"output","notes":{"family":"Communication","what":"Posts simple messages through a saved Slack Incoming Webhook","overview":"Send a simple Slack message through a saved Slack Incoming Webhook connection.","tips":["Save the Incoming Webhook URL as a Connection","The target channel is chosen when the webhook is created in Slack","Use Slack Message for OAuth bot sending, dynamic channels, and Block Kit","This node's output replaces $json entirely â€” fields from before this node do not survive past it, so capture anything needed later first","Failures set status to \"failed\" and add a plain error field (no underscore), unlike most nodes' _error convention"],"docsHref":"/docs/nodes/slack_webhook","why":"Notifies the finance channel immediately."}},"type":"custom","position":{"x":2660,"y":300}},{"id":"email_finance_alert","data":{"icon":"Mail","type":"google_gmail","label":"Email Finance Manager","config":{"to":"REPLACE_WITH_YOUR_FINANCE_TEAM_EMAIL","body":"{{input.alert}}","subject":"Compliance Alert - Transaction Review Required","operation":"send"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Emails the finance manager as well, because a Slack message at 6pm on Friday gets missed."}},"type":"custom","position":{"x":2980,"y":300}},{"id":"log_flagged","data":{"icon":"FileOutput","type":"log_output","label":"Log Flagged","config":{"level":"warn","message":"Transaction flagged: ${{input.transaction.amount}} - {{input.transaction.vendor}} - Violations: {{input.violations.length}}"},"category":"utility","notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"Records the flag for audit."}},"type":"custom","position":{"x":3300,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"webhook_finance_1","target":"js_extract_transaction"},{"id":"e2","source":"js_extract_transaction","target":"ai_categorize"},{"id":"e3","source":"ai_categorize","target":"js_parse_category"},{"id":"e4","source":"js_parse_category","target":"js_compliance_check"},{"id":"e5","source":"js_compliance_check","target":"if_compliant_check"},{"id":"e6","source":"if_compliant_check","target":"db_save_transaction","sourceHandle":"true"},{"id":"e7","source":"if_compliant_check","target":"db_save_flag","sourceHandle":"false"},{"id":"e8","source":"db_save_transaction","target":"log_approved"},{"id":"e9","source":"db_save_flag","target":"js_format_alert"},{"id":"e10","source":"js_format_alert","target":"slack_finance_alert"},{"id":"e11","source":"slack_finance_alert","target":"email_finance_alert"},{"id":"e12","source":"email_finance_alert","target":"log_flagged"}]$tpl$::jsonb,
    difficulty           = $tpl$Advanced$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$finance$tpl$,$tpl$compliance$tpl$,$tpl$invoicing$tpl$,$tpl$expenses$tpl$,$tpl$categorization$tpl$,$tpl$audit$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$9fff0187-8a5b-4f12-bf80-0d3b88737190$tpl$;

-- HR / Hiring Workflow Agent
UPDATE templates SET
    name                 = $tpl$HR / Hiring Workflow Agent$tpl$,
    description          = $tpl$Automated resume processing agent that extracts skills, matches candidates against job requirements, scores applications, and automatically schedules interviews for shortlisted candidates.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"webhook_resume_1","data":{"icon":"Webhook","type":"webhook","label":"Resume Webhook","config":{"method":"POST"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives applications from your careers page or job board."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_extract_resume_data","data":{"icon":"Code","type":"javascript","label":"Extract Resume Data","config":{"code":"return { name: input.name || input.candidate_name || 'Unknown', email: input.email || input.candidate_email || '', resume_text: input.resume_text || input.resume || input.text || '', job_role: input.job_role || input.position || '', resume_file_url: input.resume_file_url || input.file_url || '', timestamp: new Date().toISOString() };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Normalises the varying field names applicant sources use."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_extract_skills","data":{"icon":"Brain","type":"openai_gpt","label":"Extract Skills","config":{"model":"gpt-4o-mini","memory":3,"prompt":"Extract skills, experience, education, and qualifications from this resume. Return a JSON object: { skills: [\"skill1\", \"skill2\"], experience_years: number, education: string, certifications: [\"cert1\"], summary: string }\\n\\nResume text: {{input.resume_text}}","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Pulls structured skills, years and education out of free-form resume text — the step that makes automated matching possible at all."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_parse_skills","data":{"icon":"Code","type":"javascript","label":"Parse Skills","config":{"code":"try { const content = input.content || input.text || input.response || '{}'; const jsonMatch = content.match(/\\{[\\s\\S]*\\}/); if (jsonMatch) { const parsed = JSON.parse(jsonMatch[0]); return { skills: parsed.skills || [], experience_years: parsed.experience_years || 0, education: parsed.education || '', certifications: parsed.certifications || [], summary: parsed.summary || '', originalData: input }; } return { skills: [], experience_years: 0, education: '', certifications: [], summary: '', originalData: input }; } catch (e) { return { skills: [], experience_years: 0, education: '', certifications: [], summary: '', originalData: input }; }"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Converts the AI's JSON into real fields for the matching step."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"ai_match_job","data":{"icon":"Brain","type":"openai_gpt","label":"Match Against Job Role","config":{"model":"gpt-4o-mini","memory":3,"prompt":"Match this candidate against the job role: {{input.job_role}}. Candidate skills: {{input.skills}}, Experience: {{input.experience_years}} years, Education: {{input.education}}. Return JSON: { match_score: number (0-100), shortlisted: boolean (score >= 70), strengths: [\"strength1\"], gaps: [\"gap1\"], recommendation: string }","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Scores the candidate against the role and explains its reasoning, so a human reviewing the decision can see why."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"js_extract_match","data":{"icon":"Code","type":"javascript","label":"Extract Match Result","config":{"code":"try { const content = input.content || input.text || input.response || '{}'; const jsonMatch = content.match(/\\{[\\s\\S]*\\}/); if (jsonMatch) { const parsed = JSON.parse(jsonMatch[0]); return { match_score: parsed.match_score || 0, shortlisted: parsed.shortlisted !== undefined ? parsed.shortlisted : (parsed.match_score >= 70), strengths: parsed.strengths || [], gaps: parsed.gaps || [], recommendation: parsed.recommendation || 'No recommendation', candidateData: input.originalData }; } return { match_score: 0, shortlisted: false, strengths: [], gaps: [], recommendation: 'Could not parse match result', candidateData: input.originalData }; } catch (e) { return { match_score: 0, shortlisted: false, strengths: [], gaps: [], recommendation: 'Error: ' + e.message, candidateData: input.originalData }; }"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Extracts the score and shortlist decision from the AI reply."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"if_shortlist_check","data":{"icon":"GitBranch","type":"if_else","label":"Check Shortlist","config":{"conditions":[{"field":"$json.shortlisted","operator":"equals","value":true}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"The hiring decision point. 70 is the threshold, set in the matching prompt above."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"db_shortlist","data":{"icon":"Database","type":"postgresql","label":"Save to Shortlist","config":{"query":"INSERT INTO candidates (name, email, job_role, match_score, status, skills, experience_years, created_at) VALUES ('{{input.candidateData.name}}', '{{input.candidateData.email}}', '{{input.candidateData.job_role}}', {{input.match_score}}, 'shortlisted', '{{input.candidateData.skills}}', {{input.candidateData.experience_years}}, now())"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Records the shortlisted candidate. The candidates table must already exist with matching columns."}},"type":"custom","position":{"x":2340,"y":205}},{"id":"js_generate_calendar","data":{"icon":"Code","type":"javascript","label":"Generate Calendar Link","config":{"code":"// Set this to your own interview scheduling link when you set up the template.\nconst baseUrl = input.interviewBookingUrl || \"REPLACE_WITH_YOUR_INTERVIEW_BOOKING_LINK\";\nconst params = new URLSearchParams({ name: input.candidateData.name || \"\", email: input.candidateData.email || \"\", job: input.candidateData.job_role || \"\" });\nreturn {\n  ...input,\n  calendarLink: baseUrl + \"?\" + params.toString(),\n  email: input.candidateData.email,\n  name: input.candidateData.name,\n  jobRole: input.candidateData.job_role\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Builds a personalised booking link. Replace the placeholder URL with your own scheduling link."}},"type":"custom","position":{"x":2660,"y":205}},{"id":"email_interview","data":{"icon":"Mail","type":"google_gmail","label":"Send Interview Invite","config":{"to":"{{input.email}}","body":"Hi {{input.name}},\\n\\nCongratulations! We were impressed with your application for the {{input.jobRole}} position. We'd like to invite you for an interview.\\n\\nSchedule your interview: {{input.calendarLink}}\\n\\nLooking forward to meeting you!\\n\\nBest regards,\\nHR Team","subject":"Interview Invitation - {{input.jobRole}}","operation":"send"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Invites the candidate to book directly, removing the back-and-forth from scheduling."}},"type":"custom","position":{"x":2980,"y":300}},{"id":"db_reject","data":{"icon":"Database","type":"postgresql","label":"Record Rejection","config":{"query":"INSERT INTO candidates (name, email, job_role, match_score, status, reason, created_at) VALUES ('{{input.candidateData.name}}', '{{input.candidateData.email}}', '{{input.candidateData.job_role}}', {{input.match_score}}, 'rejected', '{{input.recommendation}}', now())"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Records the decision and the reasoning behind it — needed if a rejection is ever questioned."}},"type":"custom","position":{"x":2340,"y":395}},{"id":"email_rejection","data":{"icon":"Mail","type":"google_gmail","label":"Send Rejection Draft to Recruiter","config":{"to":"REPLACE_WITH_YOUR_RECRUITER_EMAIL","body":"A candidate scored below the shortlist threshold. Review and send this yourself if you agree.\n\nCandidate: {{input.candidateData.name}} <{{input.candidateData.email}}>\nRole: {{input.candidateData.job_role}}\nMatch score: {{input.match_score}}\nAI reasoning: {{input.recommendation}}\n\n--- Draft message ---\nHi {{input.candidateData.name}},\n\nThank you for your interest in the {{input.candidateData.job_role}} position. After careful consideration, we have decided to move forward with other candidates at this time.\n\nWe appreciate your interest and wish you the best in your job search.\n\nBest regards,\nHR Team","subject":"[REVIEW BEFORE SENDING] Draft rejection — {{input.candidateData.name}} ({{input.candidateData.job_role}})","operation":"send"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends a DRAFT rejection to your recruiter, not to the candidate. Automated rejections going straight out is a legal and brand risk; a person makes the final call here."}},"type":"custom","position":{"x":2660,"y":395}},{"id":"log_processing","data":{"icon":"FileOutput","type":"log_output","label":"Log Processing Result","config":{"level":"info","message":"Candidate processed: {{input.candidateData.name}} ({{input.candidateData.email}}) - Match Score: {{input.match_score}}, Shortlisted: {{input.shortlisted}}"},"category":"utility","notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"Records every application processed, whatever the outcome."}},"type":"custom","position":{"x":3300,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"webhook_resume_1","target":"js_extract_resume_data"},{"id":"e2","source":"js_extract_resume_data","target":"ai_extract_skills"},{"id":"e3","source":"ai_extract_skills","target":"js_parse_skills"},{"id":"e4","source":"js_parse_skills","target":"ai_match_job"},{"id":"e5","source":"ai_match_job","target":"js_extract_match"},{"id":"e6","source":"js_extract_match","target":"if_shortlist_check"},{"id":"e7","source":"if_shortlist_check","target":"db_shortlist","sourceHandle":"true"},{"id":"e8","source":"if_shortlist_check","target":"db_reject","sourceHandle":"false"},{"id":"e9","source":"db_shortlist","target":"js_generate_calendar"},{"id":"e10","source":"js_generate_calendar","target":"email_interview"},{"id":"e11","source":"email_interview","target":"log_processing"},{"id":"e12","source":"db_reject","target":"email_rejection"},{"id":"e13","source":"email_rejection","target":"log_processing"}]$tpl$::jsonb,
    difficulty           = $tpl$Advanced$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$hr$tpl$,$tpl$hiring$tpl$,$tpl$resume$tpl$,$tpl$recruitment$tpl$,$tpl$interview-scheduling$tpl$]::text[],
    version              = 2,
