-- Insurance Pre-Authorization Tracker (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000004$tpl$, $tpl$Insurance Pre-Authorization Tracker$tpl$, $tpl$Poll pre-authorization requests, notify staff or patients based on status, and stamp the request as checked.$tpl$, $tpl$Healthcare & Clinics$tpl$,
  $tpl$[{"id":"schedule_preauth_check","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check Pre-Authorizations","category":"triggers","config":{"cron":"*/30 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Pre-authorization status changes are periodic, so polling is safer than manual checking."}}},{"id":"airtable_read_preauth","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One Pending Request","category":"data","config":{"baseId":"","tableId":"PreAuthorizations","operation":"read","filterByFormula":"AND({Status}!='Closed', {LastCheckedAt}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Handles one pending request per run to avoid duplicate notifications."}}},{"id":"js_prepare_preauth","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Prepare Status Message","category":"data","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasRequest: false };\nconst f = rec.fields || {};\nconst status = f.Status || \"Pending\";\nreturn { ...input, hasRequest: true, recordId: rec.id, patientName: f.PatientName || \"patient\", contactEmail: f.Email || \"\", status, needsStaff: status === \"Denied\" || status === \"More Info Needed\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Normalises the pre-authorization row into the status and routing fields used below."}}},{"id":"if_has_preauth","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Request Found?","category":"logic","config":{"conditions":[{"field":"$json.hasRequest","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Stops empty polls from creating noise."}}},{"id":"if_preauth_staff","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Staff Action?","category":"logic","config":{"conditions":[{"field":"$json.needsStaff","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Separates requests that need staff intervention from simple patient updates."}}},{"id":"slack_preauth_staff","type":"custom","position":{"x":1700,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Notify Insurance Desk","category":"output","config":{"channel":"#insurance-desk","message":"Pre-authorization needs action for {{input.patientName}}. Status: {{input.status}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Gets denied or information-needed cases in front of the insurance desk."}}},{"id":"gmail_preauth_patient","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Email Patient Status","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.contactEmail}}","subject":"Insurance pre-authorization status","body":"Hi {{input.patientName}},\n\nYour current pre-authorization status is: {{input.status}}."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Keeps patients informed when the request does not need immediate staff action."}}},{"id":"airtable_mark_preauth","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Stamp Checked","category":"data","config":{"baseId":"","tableId":"PreAuthorizations","operation":"update","recordId":"{{input.recordId}}","fields":{"LastCheckedAt":"Checked"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Marks the request so it is not processed repeatedly."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_preauth_check_airtable_read_preauth","source":"schedule_preauth_check","target":"airtable_read_preauth"},{"id":"e_2_airtable_read_preauth_js_prepare_preauth","source":"airtable_read_preauth","target":"js_prepare_preauth"},{"id":"e_3_js_prepare_preauth_if_has_preauth","source":"js_prepare_preauth","target":"if_has_preauth"},{"id":"e_4_if_has_preauth_if_preauth_staff","source":"if_has_preauth","target":"if_preauth_staff","sourceHandle":"true"},{"id":"e_5_if_preauth_staff_slack_preauth_staff","source":"if_preauth_staff","target":"slack_preauth_staff","sourceHandle":"true"},{"id":"e_6_if_preauth_staff_gmail_preauth_patient","source":"if_preauth_staff","target":"gmail_preauth_patient","sourceHandle":"false"},{"id":"e_7_slack_preauth_staff_airtable_mark_preauth","source":"slack_preauth_staff","target":"airtable_mark_preauth"},{"id":"e_8_gmail_preauth_patient_airtable_mark_preauth","source":"gmail_preauth_patient","target":"airtable_mark_preauth"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  22, ARRAY[$tpl$healthcare$tpl$,$tpl$insurance$tpl$,$tpl$airtable$tpl$,$tpl$slack$tpl$,$tpl$email$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$Insurance Pre-Authorization Tracker$tpl$,
    description          = $tpl$Poll pre-authorization requests, notify staff or patients based on status, and stamp the request as checked.$tpl$,
    category             = $tpl$Healthcare & Clinics$tpl$,
    nodes                = $tpl$[{"id":"schedule_preauth_check","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check Pre-Authorizations","category":"triggers","config":{"cron":"*/30 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Pre-authorization status changes are periodic, so polling is safer than manual checking."}}},{"id":"airtable_read_preauth","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One Pending Request","category":"data","config":{"baseId":"","tableId":"PreAuthorizations","operation":"read","filterByFormula":"AND({Status}!='Closed', {LastCheckedAt}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Handles one pending request per run to avoid duplicate notifications."}}},{"id":"js_prepare_preauth","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Prepare Status Message","category":"data","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasRequest: false };\nconst f = rec.fields || {};\nconst status = f.Status || \"Pending\";\nreturn { ...input, hasRequest: true, recordId: rec.id, patientName: f.PatientName || \"patient\", contactEmail: f.Email || \"\", status, needsStaff: status === \"Denied\" || status === \"More Info Needed\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Normalises the pre-authorization row into the status and routing fields used below."}}},{"id":"if_has_preauth","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Request Found?","category":"logic","config":{"conditions":[{"field":"$json.hasRequest","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Stops empty polls from creating noise."}}},{"id":"if_preauth_staff","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Staff Action?","category":"logic","config":{"conditions":[{"field":"$json.needsStaff","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Separates requests that need staff intervention from simple patient updates."}}},{"id":"slack_preauth_staff","type":"custom","position":{"x":1700,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Notify Insurance Desk","category":"output","config":{"channel":"#insurance-desk","message":"Pre-authorization needs action for {{input.patientName}}. Status: {{input.status}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Gets denied or information-needed cases in front of the insurance desk."}}},{"id":"gmail_preauth_patient","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Email Patient Status","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.contactEmail}}","subject":"Insurance pre-authorization status","body":"Hi {{input.patientName}},\n\nYour current pre-authorization status is: {{input.status}}."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Keeps patients informed when the request does not need immediate staff action."}}},{"id":"airtable_mark_preauth","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Stamp Checked","category":"data","config":{"baseId":"","tableId":"PreAuthorizations","operation":"update","recordId":"{{input.recordId}}","fields":{"LastCheckedAt":"Checked"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Marks the request so it is not processed repeatedly."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_schedule_preauth_check_airtable_read_preauth","source":"schedule_preauth_check","target":"airtable_read_preauth"},{"id":"e_2_airtable_read_preauth_js_prepare_preauth","source":"airtable_read_preauth","target":"js_prepare_preauth"},{"id":"e_3_js_prepare_preauth_if_has_preauth","source":"js_prepare_preauth","target":"if_has_preauth"},{"id":"e_4_if_has_preauth_if_preauth_staff","source":"if_has_preauth","target":"if_preauth_staff","sourceHandle":"true"},{"id":"e_5_if_preauth_staff_slack_preauth_staff","source":"if_preauth_staff","target":"slack_preauth_staff","sourceHandle":"true"},{"id":"e_6_if_preauth_staff_gmail_preauth_patient","source":"if_preauth_staff","target":"gmail_preauth_patient","sourceHandle":"false"},{"id":"e_7_slack_preauth_staff_airtable_mark_preauth","source":"slack_preauth_staff","target":"airtable_mark_preauth"},{"id":"e_8_gmail_preauth_patient_airtable_mark_preauth","source":"gmail_preauth_patient","target":"airtable_mark_preauth"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 22,
    tags                 = ARRAY[$tpl$healthcare$tpl$,$tpl$insurance$tpl$,$tpl$airtable$tpl$,$tpl$slack$tpl$,$tpl$email$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Internal Knowledge / Ops Agent
UPDATE templates SET
    name                 = $tpl$Internal Knowledge / Ops Agent$tpl$,
    description          = $tpl$Internal knowledge base assistant that searches company documentation, answers employee questions with source citations, and escalates when information is not found. Perfect for employee self-service.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"chat_trigger_kb_1","data":{"icon":"MessageSquare","type":"chat_trigger","label":"Internal Chat Trigger","config":{},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Where employees ask their question."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_prepare_query","data":{"icon":"Code","type":"javascript","label":"Prepare Query","config":{"code":"const raw = (typeof input === 'string') ? input : (input && (input.message || input.query || input.text)) || '';\nconst obj = (typeof input === \"object\" && input) ? input : {};\nreturn {\n  ...obj,\n  query: raw,\n  user: obj.user || obj.user_id || \"unknown\",\n  timestamp: new Date().toISOString(),\n  context: obj.context || \"\"\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Prepares the question and captures who asked. Written to work whether the chat trigger hands over a string or an object."}},"type":"custom","position":{"x":420,"y":300}},{"id":"db_search_kb","data":{"icon":"Database","type":"postgresql","label":"Search Knowledge Base","config":{"query":"SELECT title, content, url, updated_at FROM knowledge_base WHERE title ILIKE '%{{input.query}}%' OR content ILIKE '%{{input.query}}%' ORDER BY updated_at DESC LIMIT 5"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Searches your knowledge base for articles matching the question. The ILIKE search on title and content is what makes the answer relevant — the previous version returned five arbitrary rows regardless of what was asked."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_format_kb_results","data":{"icon":"Code","type":"javascript","label":"Format KB Results","config":{"code":"// The PostgreSQL node returns { rows, rowsAffected }.\nconst results = input.rows || [];\nif (results.length === 0) {\n  return { ...input, found: false, content: \"\", contentLength: 0, sources: [] };\n}\nconst content = results.map((r, i) => (i + 1) + \". \" + (r.title || \"Untitled\") + \"\\n\" + (r.content || r.body || \"\")).join(\"\\n\\n---\\n\\n\");\nconst sources = results.map(r => ({ title: r.title || \"Untitled\", url: r.url || \"\", updated_at: r.updated_at || \"\" }));\n// contentLength is emitted so the gate below can test it as its own condition —\n// the runtime evaluates one comparison per row and cannot parse \"a && b\".\nreturn { ...input, found: true, content, contentLength: content.length, sources, query: input.query };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Assembles the retrieved articles into one block for the AI and reports how much content was found, which the gate below tests."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"if_kb_found","data":{"icon":"GitBranch","type":"if_else","label":"Check if Found","config":{"conditions":[{"field":"$json.found","operator":"equals","value":true},{"field":"$json.contentLength","operator":"greater_than","value":0}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Decides whether there is enough material to answer from. Two separate conditions, because the runtime evaluates one comparison per row — a combined 'a && b' expression silently never matches."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"ai_answer_with_sources","data":{"icon":"Brain","type":"openai_gpt","label":"Generate Answer with Sources","config":{"model":"gpt-4o-mini","memory":10,"prompt":"You are an internal knowledge assistant. Answer the employee's question based on the knowledge base content provided. Always cite sources.\\n\\nEmployee Question: {{input.query}}\\n\\nKnowledge Base Content:\\n{{input.content}}\\n\\nProvide a clear, helpful answer with source citations. Format: Answer text followed by \\\"Sources: [source1, source2]\\\"","temperature":0.5},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Answers from the retrieved articles and cites them, so an employee can verify rather than trust."}},"type":"custom","position":{"x":1700,"y":205}},{"id":"js_format_response","data":{"icon":"Code","type":"javascript","label":"Format Response","config":{"code":"const answer = input.content || input.text || input.response || 'I found some information for you.'; const sources = input.sources || []; const sourcesText = sources.length > 0 ? '\\n\\nSources:\\n' + sources.map((s, i) => `${i + 1}. ${s.title}${s.url ? ' (' + s.url + ')' : ''}`).join('\\n') : ''; return { answer: answer + sourcesText, sources, query: input.query };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Appends the source list to the answer."}},"type":"custom","position":{"x":2020,"y":205}},{"id":"db_log_query","data":{"icon":"Database","type":"postgresql","label":"Log Answered Question","config":{"query":"INSERT INTO kb_queries (query, answer, sources_count, found, \"user\", created_at) VALUES ('{{input.query}}', '{{input.answer}}', {{input.sources.length}}, true, '{{input.user}}', now())"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Records answered questions — the log that tells you what your team actually needs documented."}},"type":"custom","position":{"x":2340,"y":205}},{"id":"ai_fallback_answer","data":{"icon":"Brain","type":"openai_gpt","label":"Generate Fallback Answer","config":{"model":"gpt-4o-mini","memory":5,"prompt":"An employee asked: \\\"{{input.query}}\\\"\\n\\nNo relevant information was found in the knowledge base. Provide a polite response explaining that the information is not available, and suggest they contact the appropriate team or check back later. Keep it brief and helpful.","temperature":0.7},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Says 'not in the knowledge base' politely and points elsewhere, instead of the AI inventing an answer."}},"type":"custom","position":{"x":1700,"y":395}},{"id":"db_log_not_found","data":{"icon":"Database","type":"postgresql","label":"Log Knowledge Gap","config":{"query":"INSERT INTO kb_queries (query, answer, found, \"user\", created_at) VALUES ('{{input.query}}', '{{input.response}}', false, '{{input.user}}', now())"},"category":"data","notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Records the gap. Over time this becomes your documentation backlog."}},"type":"custom","position":{"x":2020,"y":395}},{"id":"slack_escalate_kb","data":{"icon":"MessageCircle","type":"slack_webhook","label":"Notify Knowledge Team","config":{"message":"📚 Knowledge Gap Identified\\nQuery: {{input.query}}\\nUser: {{input.user}}\\nConsider adding this to the knowledge base.","username":"KB Bot","webhookUrl":"REPLACE_WITH_YOUR_SLACK_INCOMING_WEBHOOK_URL"},"category":"output","notes":{"family":"Communication","what":"Posts simple messages through a saved Slack Incoming Webhook","overview":"Send a simple Slack message through a saved Slack Incoming Webhook connection.","tips":["Save the Incoming Webhook URL as a Connection","The target channel is chosen when the webhook is created in Slack","Use Slack Message for OAuth bot sending, dynamic channels, and Block Kit","This node's output replaces $json entirely â€” fields from before this node do not survive past it, so capture anything needed later first","Failures set status to \"failed\" and add a plain error field (no underscore), unlike most nodes' _error convention"],"docsHref":"/docs/nodes/slack_webhook","why":"Tells the knowledge team a question could not be answered so the gap gets filled."}},"type":"custom","position":{"x":2340,"y":395}},{"id":"merge_responses_kb","data":{"icon":"GitMerge","type":"merge","label":"Merge Responses","config":{},"category":"logic","notes":{"family":"Logic","what":"Combines results coming from two paths into one","overview":"Rejoins multiple workflow branches and combines their data into one payload for the next step.","tips":["Use overwrite for simple flat objects when duplicate keys can be replaced.","Use append when the next node should receive a list at {{$json.items}}.","Use deep_merge when branches add different nested details that should survive together.","Connect every branch that should rejoin into Merge, then connect Merge output to the final action."],"docsHref":"/docs/nodes/merge","why":"Brings both branches back together so the reply is returned once."}},"type":"custom","position":{"x":2660,"y":300}},{"id":"log_output_kb","data":{"icon":"FileOutput","type":"log_output","label":"Return Answer","config":{"level":"info","message":"{{input.answer || input.content || input.text || input.response}}"},"category":"utility","notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"Returns the final answer to the employee."}},"type":"custom","position":{"x":2980,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"chat_trigger_kb_1","target":"js_prepare_query"},{"id":"e2","source":"js_prepare_query","target":"db_search_kb"},{"id":"e3","source":"db_search_kb","target":"js_format_kb_results"},{"id":"e4","source":"js_format_kb_results","target":"if_kb_found"},{"id":"e5","source":"if_kb_found","target":"ai_answer_with_sources","sourceHandle":"true"},{"id":"e6","source":"if_kb_found","target":"ai_fallback_answer","sourceHandle":"false"},{"id":"e7","source":"ai_answer_with_sources","target":"js_format_response"},{"id":"e8","source":"js_format_response","target":"db_log_query"},{"id":"e9","source":"ai_fallback_answer","target":"db_log_not_found"},{"id":"e10","source":"db_log_not_found","target":"slack_escalate_kb"},{"id":"e11","source":"db_log_query","target":"merge_responses_kb"},{"id":"e12","source":"slack_escalate_kb","target":"merge_responses_kb"},{"id":"e13","source":"merge_responses_kb","target":"log_output_kb"}]$tpl$::jsonb,
    difficulty           = $tpl$Advanced$tpl$,
    estimated_setup_time = 10,
    tags                 = ARRAY[$tpl$knowledge-base$tpl$,$tpl$internal-ops$tpl$,$tpl$documentation$tpl$,$tpl$qa$tpl$,$tpl$employee-assistant$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$5b3d400a-0eec-4c09-ac51-921cd6a35a50$tpl$;

-- Invoice Approval Triage (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000006$tpl$, $tpl$Invoice Approval Triage$tpl$, $tpl$Accept invoice submissions, classify policy risk, route high-value or suspicious invoices to finance, and store the decision.$tpl$, $tpl$Finance, Accounting & Insurance$tpl$,
  $tpl$[{"id":"form_invoice_submission","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Invoice Submission Form","category":"triggers","config":{"fields":[{"key":"vendor","type":"text","label":"Vendor","required":true},{"key":"amount","type":"number","label":"Amount","required":true},{"key":"description","type":"textarea","label":"Description","required":true},{"key":"submitterEmail","type":"email","label":"Submitter Email","required":true}],"formTitle":"Invoice Approval","submitButtonText":"Submit Invoice"},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects the vendor, amount and context needed for an approval decision."}}},{"id":"ai_invoice_risk","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Assess Invoice Risk","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Assess this invoice. Vendor: {{input.vendor}}. Amount: {{input.amount}}. Description: {{input.description}}. Return ONLY JSON: {\"requiresApproval\":true|false,\"risk\":\"low|medium|high\",\"reason\":\"short reason\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Adds policy/risk judgment beyond a simple amount threshold."}}},{"id":"js_parse_invoice","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Approval Decision","category":"data","config":{"code":"let parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nconst amount = Number(input.amount || 0);\nreturn { ...input, amount, requiresApproval: parsed.requiresApproval === true || amount >= 5000, risk: parsed.risk || \"medium\", reason: parsed.reason || \"\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Combines AI judgment with a hard approval threshold into a reliable flag."}}},{"id":"if_invoice_approval","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Approval Required?","category":"logic","config":{"conditions":[{"field":"$json.requiresApproval","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Separates invoices finance must review from those that can be filed."}}},{"id":"postgres_log_invoice","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Box","type":"postgresql","label":"Log Invoice Decision","category":"data","config":{"query":"INSERT INTO invoice_reviews (vendor, amount, risk, requires_approval, reason, submitter_email, created_at) VALUES ('{{input.vendor}}', {{input.amount}}, '{{input.risk}}', '{{input.requiresApproval}}', '{{input.reason}}', '{{input.submitterEmail}}', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Creates an audit record for every invoice decision."}}},{"id":"slack_invoice_approval","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Finance Approver","category":"output","config":{"channel":"#finance-approvals","message":"Invoice needs approval: {{input.vendor}} - {{input.amount}}\nRisk: {{input.risk}}\nReason: {{input.reason}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts approval-required invoices in the finance queue immediately."}}},{"id":"gmail_invoice_received","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Mail","type":"google_gmail","label":"Email Submitter","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.submitterEmail}}","subject":"Invoice received: {{input.vendor}}","body":"Your invoice submission was received. Approval required: {{input.requiresApproval}}. Reason: {{input.reason}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Confirms receipt so the submitter knows the invoice is in process."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_invoice_submission_ai_invoice_risk","source":"form_invoice_submission","target":"ai_invoice_risk"},{"id":"e_2_ai_invoice_risk_js_parse_invoice","source":"ai_invoice_risk","target":"js_parse_invoice"},{"id":"e_3_js_parse_invoice_if_invoice_approval","source":"js_parse_invoice","target":"if_invoice_approval"},{"id":"e_4_if_invoice_approval_slack_invoice_approval","source":"if_invoice_approval","target":"slack_invoice_approval","sourceHandle":"true"},{"id":"e_5_if_invoice_approval_postgres_log_invoice","source":"if_invoice_approval","target":"postgres_log_invoice","sourceHandle":"false"},{"id":"e_6_slack_invoice_approval_postgres_log_invoice","source":"slack_invoice_approval","target":"postgres_log_invoice"},{"id":"e_7_postgres_log_invoice_gmail_invoice_received","source":"postgres_log_invoice","target":"gmail_invoice_received"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
