-- License Renewal Reminder
UPDATE templates SET
    name                 = $tpl$License Renewal Reminder$tpl$,
    description          = $tpl$Licenses and registrations expire quietly — this workflow checks your stored expiry dates every day and sends escalating email reminders at the 90, 30, and 7-day marks, so nothing lapses without warning.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"schedule_daily_check","data":{"icon":"Clock","type":"schedule","label":"Check Every 10 Minutes","config":{"cron":"*/10 * * * *","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs every 10 minutes and handles one licence per run, which clears any realistic renewal queue within the day."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_expiry_dates","data":{"icon":"Database","type":"airtable","label":"Read Stored Expiry Dates","config":{"baseId":"","tableId":"Licenses","operation":"read","filterByFormula":"AND({ExpiryDate} <= DATEADD(TODAY(), 90, 'days'), OR({LastRemindedMilestone} = '', {LastRemindedMilestone} != CONCATENATE('', DATETIME_DIFF({ExpiryDate}, TODAY(), 'days'))))","maxRecords":1,"sort":[{"field":"ExpiryDate","direction":"asc"}]},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Picks up one licence approaching expiry that has not been reminded at its current milestone."}},"type":"custom","position":{"x":420,"y":300}},{"id":"js_flag_expiring","data":{"icon":"Code","type":"javascript","label":"Select Licence & Milestone","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, shouldRemind: false };\nconst f = rec.fields || {};\nconst DAY = 86400000;\nconst daysLeft = Math.round((new Date(f.ExpiryDate).getTime() - Date.now()) / DAY);\n// Only the three milestones the template promises — not every day in between.\nlet milestone = null;\nif (daysLeft <= 7) milestone = 7;\nelse if (daysLeft <= 30) milestone = 30;\nelse if (daysLeft <= 90) milestone = 90;\nconst urgency = milestone === 7 ? \"urgent\" : milestone === 30 ? \"soon\" : \"upcoming\";\nreturn {\n  ...input,\n  shouldRemind: milestone !== null,\n  recordId: rec.id,\n  milestone,\n  urgency,\n  daysLeft,\n  licenseName: f.LicenseName || f.Name || \"your licence\",\n  expiryDate: f.ExpiryDate || \"\",\n  contactEmail: f.Email || \"\"\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Works out how many days remain and which milestone band the licence is in. The 90 / 30 / 7 day bands are set here."}},"type":"custom","position":{"x":740,"y":300}},{"id":"gmail_send_backup_reminder","data":{"icon":"Mail","type":"google_gmail","label":"Send Email Reminder","config":{"body":"Your {{input.licenseName}} expires on {{input.expiryDate}} — {{input.daysLeft}} days from now. Please renew soon to avoid a lapse.","subject":"License renewal reminder: {{input.licenseName}} ({{input.daysLeft}} days left)","operation":"send","recipientEmails":"{{input.contactEmail}}","recipientSource":"manual_entry"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Emails the client at the right milestone. This is the deliverable, and the marker above prevents repeat reminders."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"airtable_mark_reminded","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Database","type":"airtable","label":"Record Reminder Sent","category":"data","config":{"baseId":"","tableId":"Licenses","operation":"update","recordId":"{{input.recordId}}","fields":{"LastRemindedMilestone":"{{input.milestone}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Records which milestone was sent. Delete this and the client receives the same reminder every 10 minutes until the licence expires."}}},{"id":"if_shouldremind","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Any Licence at a Milestone?","category":"logic","config":{"conditions":[{"field":"$json.shouldRemind","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Most runs find nothing. Without this the workflow would send a blank email on every empty poll."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_daily_check","target":"airtable_read_expiry_dates"},{"id":"e2","source":"airtable_read_expiry_dates","target":"js_flag_expiring"},{"id":"e3","source":"if_shouldremind","target":"airtable_mark_reminded","sourceHandle":"true"},{"id":"e4","source":"airtable_mark_reminded","target":"gmail_send_backup_reminder"},{"id":"e_js_flag_expiring_if_shouldremind","source":"js_flag_expiring","target":"if_shouldremind"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$compliance$tpl$,$tpl$reminders$tpl$,$tpl$email$tpl$,$tpl$airtable$tpl$,$tpl$scheduling$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$c432444a-1326-42dc-ad12-7c1530d0be68$tpl$;

-- Live Status Lookup Bot
UPDATE templates SET
    name                 = $tpl$Live Status Lookup Bot$tpl$,
    description          = $tpl$The simplest way to check where a client stands without opening Airtable or asking someone else to look it up. Type a client name or order number in chat and get back a clean, formatted status straight from the live record.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"chat_trigger_status","data":{"icon":"MessageSquare","type":"chat_trigger","label":"Status Question","config":{},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Lets anyone check a client's status without opening Airtable or asking a colleague."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_parse_lookup","data":{"icon":"Code","type":"javascript","label":"Parse Client Name / Order Number","config":{"code":"const raw = (typeof input === 'string') ? input : (input && (input.message || input.query || input.text)) || '';\nreturn { ...(typeof input === \"object\" && input ? input : {}), lookupValue: raw.trim() };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Takes the raw chat message as the search term. Written to work whether the chat trigger hands over a string or an object."}},"type":"custom","position":{"x":420,"y":300}},{"id":"airtable_lookup_status","data":{"icon":"Database","type":"airtable","label":"Lookup Live Record","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"SEARCH(LOWER('{{input.lookupValue}}'), LOWER({Name}))","maxRecords":1},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Finds the matching client. The name filter is essential — without it the bot returns the same first row no matter what was asked."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_format_reply","data":{"icon":"Code","type":"javascript","label":"Format Clean Reply","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) {\n  return { ...input, reply: \"I could not find a client matching \\\"\" + input.lookupValue + \"\\\". Check the spelling, or try part of the name.\" };\n}\nconst f = rec.fields || {};\nconst reply = \"Status for \" + (f.Name || input.lookupValue) + \": \" + (f.Status || \"unknown\") +\n  \". Score: \" + (f.Score != null ? f.Score : \"n/a\") +\n  \". Missing docs: \" + (f.Missing || \"none on file\") + \".\";\nreturn { ...input, reply };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the record into a readable sentence, and says so plainly when nothing matched instead of returning a half-empty status line."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"slack_send_status_reply","data":{"icon":"MessageCircle","type":"slack_message","label":"Send Status Reply","config":{"channel":"{{input.channel}}","message":"{{input.reply}}"},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Replies in the channel where the question was asked."}},"type":"custom","position":{"x":1380,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"chat_trigger_status","target":"js_parse_lookup"},{"id":"e2","source":"js_parse_lookup","target":"airtable_lookup_status"},{"id":"e3","source":"airtable_lookup_status","target":"js_format_reply"},{"id":"e4","source":"js_format_reply","target":"slack_send_status_reply"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 12,
    tags                 = ARRAY[$tpl$chatbot$tpl$,$tpl$lookup$tpl$,$tpl$airtable$tpl$,$tpl$slack$tpl$,$tpl$status$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$1773b93e-cd04-42a9-914e-96e93dfe4bd6$tpl$;

-- Meeting Notes to Action Items (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000011$tpl$, $tpl$Meeting Notes to Action Items$tpl$, $tpl$Turn meeting notes into owners and action items, store the summary, and post the task list to the team.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"form_meeting_notes","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Meeting Notes Form","category":"triggers","config":{"fields":[{"key":"meetingTitle","type":"text","label":"Meeting Title","required":true},{"key":"notes","type":"textarea","label":"Notes","required":true},{"key":"teamChannel","type":"text","label":"Team Slack Channel","required":false}],"formTitle":"Meeting Notes","submitButtonText":"Create Actions"},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Gives the team a simple way to turn raw notes into follow-up work."}}},{"id":"ai_extract_actions","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Extract Action Items","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Extract action items from these meeting notes: {{input.notes}}. Return ONLY JSON: {\"summary\":\"short summary\",\"actionsText\":\"numbered action list with owner and due date when present\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Finds action items and owners in unstructured notes."}}},{"id":"js_parse_actions","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Action Items","category":"data","config":{"code":"let parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nreturn { ...input, summary: parsed.summary || \"\", actionsText: parsed.actionsText || \"No action items found.\", channel: input.teamChannel || \"#team-updates\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Formats the AI result for storage and Slack posting."}}},{"id":"postgres_save_meeting","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Box","type":"postgresql","label":"Save Meeting Summary","category":"data","config":{"query":"INSERT INTO meeting_summaries (title, summary, actions, created_at) VALUES ('{{input.meetingTitle}}', '{{input.summary}}', '{{input.actionsText}}', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Keeps a searchable record of meeting decisions and tasks."}}},{"id":"slack_post_actions","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Actions to Team","category":"output","config":{"channel":"{{input.channel}}","message":"*{{input.meetingTitle}} actions*\n{{input.actionsText}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the follow-up list where the team already coordinates."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_meeting_notes_ai_extract_actions","source":"form_meeting_notes","target":"ai_extract_actions"},{"id":"e_2_ai_extract_actions_js_parse_actions","source":"ai_extract_actions","target":"js_parse_actions"},{"id":"e_3_js_parse_actions_postgres_save_meeting","source":"js_parse_actions","target":"postgres_save_meeting"},{"id":"e_4_postgres_save_meeting_slack_post_actions","source":"postgres_save_meeting","target":"slack_post_actions"}]$tpl$::jsonb, $tpl$Beginner$tpl$,
  15, ARRAY[$tpl$operations$tpl$,$tpl$meetings$tpl$,$tpl$actions$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$Meeting Notes to Action Items$tpl$,
    description          = $tpl$Turn meeting notes into owners and action items, store the summary, and post the task list to the team.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"form_meeting_notes","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Meeting Notes Form","category":"triggers","config":{"fields":[{"key":"meetingTitle","type":"text","label":"Meeting Title","required":true},{"key":"notes","type":"textarea","label":"Notes","required":true},{"key":"teamChannel","type":"text","label":"Team Slack Channel","required":false}],"formTitle":"Meeting Notes","submitButtonText":"Create Actions"},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Gives the team a simple way to turn raw notes into follow-up work."}}},{"id":"ai_extract_actions","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Extract Action Items","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Extract action items from these meeting notes: {{input.notes}}. Return ONLY JSON: {\"summary\":\"short summary\",\"actionsText\":\"numbered action list with owner and due date when present\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Finds action items and owners in unstructured notes."}}},{"id":"js_parse_actions","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Action Items","category":"data","config":{"code":"let parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nreturn { ...input, summary: parsed.summary || \"\", actionsText: parsed.actionsText || \"No action items found.\", channel: input.teamChannel || \"#team-updates\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Formats the AI result for storage and Slack posting."}}},{"id":"postgres_save_meeting","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Box","type":"postgresql","label":"Save Meeting Summary","category":"data","config":{"query":"INSERT INTO meeting_summaries (title, summary, actions, created_at) VALUES ('{{input.meetingTitle}}', '{{input.summary}}', '{{input.actionsText}}', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Keeps a searchable record of meeting decisions and tasks."}}},{"id":"slack_post_actions","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Actions to Team","category":"output","config":{"channel":"{{input.channel}}","message":"*{{input.meetingTitle}} actions*\n{{input.actionsText}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the follow-up list where the team already coordinates."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_form_meeting_notes_ai_extract_actions","source":"form_meeting_notes","target":"ai_extract_actions"},{"id":"e_2_ai_extract_actions_js_parse_actions","source":"ai_extract_actions","target":"js_parse_actions"},{"id":"e_3_js_parse_actions_postgres_save_meeting","source":"js_parse_actions","target":"postgres_save_meeting"},{"id":"e_4_postgres_save_meeting_slack_post_actions","source":"postgres_save_meeting","target":"slack_post_actions"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$operations$tpl$,$tpl$meetings$tpl$,$tpl$actions$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Missing Document Finder
UPDATE templates SET
    name                 = $tpl$Missing Document Finder$tpl$,
    description          = $tpl$Stop chasing clients for 'one more document.' Upload whatever paperwork a client has sent so far, in any order, and this workflow figures out exactly which required documents are still missing and emails the client a specific checklist.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"form_doc_upload","data":{"icon":"FileText","type":"form","label":"Document Upload Form","config":{"fields":[{"key":"clientName","type":"text","label":"Client / Business Name","required":true},{"key":"clientType","type":"select","label":"Client Type","required":true,"options":["Individual","Business"]},{"key":"document","type":"file","label":"Document","required":true},{"key":"contactEmail","type":"email","label":"Contact Email","required":true}],"formTitle":"Upload Your Documents","formDescription":"Upload whatever documents you have — in any order. We will tell you what is still missing.","submitButtonText":"Upload"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Lets a client upload whatever they have, in any order. The client type chosen here decides which checklist applies."}},"type":"custom","position":{"x":100,"y":300}},{"id":"ai_classify_document","data":{"icon":"Brain","type":"google_gemini","label":"Identify Document Type","config":{"model":"gemini-3.5-flash","prompt":"Look at this uploaded file (name and content provided): {{input.document}}. Identify which document type it most likely is, choosing from: GST Certificate, PAN Card, Bank Statement, Address Proof, Business Registration, Photo ID, Other. Reply with only the document type name."},"category":"ai","notes":{"family":"AI","what":"Uses Google's Gemini AI to generate text, answer questions, or analyze content","overview":"Calls Google Gemini through the LLM adapter and returns response, model, usage, and finishReason. The current executor resolves Gemini credentials from connection/wallet/key-pool/direct config, and it does not preserve incoming fields on success.","tips":[],"docsHref":"/docs/nodes/google_gemini","why":"Identifies what each uploaded file actually is, so clients do not have to label anything correctly."}},"type":"custom","position":{"x":420,"y":300}},{"id":"airtable_log_document","data":{"icon":"Database","type":"airtable","label":"Log Received Document","config":{"baseId":"","fields":{"Client":"{{input.clientName}}","DocumentType":"{{input.response}}"},"tableId":"DocumentsReceived","operation":"create"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Records the document against the client, building the running history the check below depends on."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_check_missing","data":{"icon":"Code","type":"javascript","label":"Compare Against Checklist","config":{"code":"const required = { 'Individual': ['PAN Card','Address Proof','Photo ID'], 'Business': ['GST Certificate','PAN Card','Bank Statement','Business Registration'] };\nconst checklist = required[input.clientType] || required['Business'];\n// Every document logged for this client so far, from the Airtable read above.\nconst received = (input.records || []).map(r => (r.fields && r.fields.DocumentType) || \"\").filter(Boolean);\nconst missing = checklist.filter(doc => !received.includes(doc));\nreturn { ...input, received, missing, isComplete: missing.length === 0 };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Compares the full set received against the required checklist. The two checklists — Individual and Business — are defined here."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"ai_write_missing_message","data":{"icon":"Brain","type":"openai_gpt","label":"Write Missing Docs Message","config":{"model":"gpt-4o-mini","prompt":"Write a short, friendly email message to {{input.clientName}} listing exactly which documents are still missing: {{input.missing}}. If nothing is missing, congratulate them that their file is complete. Keep it under 3 sentences.","temperature":0.6},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Writes a short, friendly chase message rather than a blunt system list."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"whatsapp_send_missing","data":{"icon":"Mail","type":"google_gmail","label":"Email Missing Docs List","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.contactEmail}}","subject":"Missing documents for {{input.clientName}}","body":"{{input.response}}"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Emails the client exactly what is still outstanding, which is what stops the back-and-forth."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"airtable_read_prior_docs","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read All Documents Received So Far","category":"data","config":{"baseId":"","tableId":"DocumentsReceived","operation":"read","filterByFormula":"{Client}='{{input.clientName}}'","maxRecords":100},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Reads everything this client has ever sent. Without this the checklist only sees the file just uploaded and reports almost everything as missing."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"form_doc_upload","target":"ai_classify_document"},{"id":"e2","source":"ai_classify_document","target":"airtable_log_document"},{"id":"e3","source":"airtable_log_document","target":"airtable_read_prior_docs"},{"id":"e4","source":"js_check_missing","target":"ai_write_missing_message"},{"id":"e5","source":"ai_write_missing_message","target":"whatsapp_send_missing"},{"id":"e_airtable_read_prior_docs_js_check_missing","source":"airtable_read_prior_docs","target":"js_check_missing"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 18,
    tags                 = ARRAY[$tpl$verification$tpl$,$tpl$onboarding$tpl$,$tpl$documents$tpl$,$tpl$ai$tpl$,$tpl$email$tpl$,$tpl$airtable$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$58703e5c-2ec9-437f-9b05-264a017e5ce8$tpl$;

-- New Client Risk Checker
UPDATE templates SET
    name                 = $tpl$New Client Risk Checker$tpl$,
    description          = $tpl$Judge new business signups on real signals instead of gut feeling. This workflow checks domain age, runs an AI risk read, scores the result, and alerts your compliance team in Slack the moment a new client crosses your risk threshold.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"form_new_client","data":{"icon":"FileText","type":"form","label":"New Business Signup Form","config":{"fields":[{"key":"businessName","type":"text","label":"Business Name","required":true},{"key":"website","type":"url","label":"Website URL","required":true},{"key":"contactEmail","type":"email","label":"Contact Email","required":true}],"formTitle":"New Client Signup","submitButtonText":"Submit"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"The signup point, and the source of the domain that gets checked below."}},"type":"custom","position":{"x":100,"y":300}},{"id":"http_domain_age_lookup","data":{"icon":"Globe","type":"http_request","label":"Check Domain Age","config":{"url":"https://www.whoisxmlapi.com/whoisserver/WhoisService?domainName={{input.website}}&apiKey=REPLACE_WITH_YOUR_WHOISXML_API_KEY&outputFormat=JSON","method":"GET","headers":{},"timeout":10000},"category":"http_api","notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Looks up how long the domain has existed. A domain registered last week is one of the strongest fraud signals available. Needs your own WHOIS API key — replace the placeholder."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_risk_summary","data":{"icon":"Brain","type":"openai_gpt","label":"Write Risk Summary","config":{"model":"gpt-4o-mini","prompt":"Assess fraud/risk signals for this new business signup. Business: {{input.businessName}}, website {{input.website}}, domain age data: {{input.body}}. A domain registered very recently, mismatched business name, or a suspicious website structure are red flags. Write a short risk summary and end with a line \"RISK_LEVEL: low|medium|high\".","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Weighs the domain age together with the business name and site, and ends with a clear risk level."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_risk_score","data":{"icon":"Code","type":"javascript","label":"Compute Risk Score & Threshold","config":{"code":"const text = input.response || input.text || '';\nconst match = text.match(/RISK_LEVEL:\\s*(low|medium|high)/i);\nconst level = match ? match[1].toLowerCase() : 'medium';\nconst scoreMap = { low: 20, medium: 55, high: 85 };\nconst riskScore = scoreMap[level];\nreturn { ...input, riskLevel: level, riskScore, isHighRisk: riskScore >= 80 };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Converts the risk level to a number and applies your threshold. 80 is where compliance gets involved — change it here."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"airtable_log_risk","data":{"icon":"Database","type":"airtable","label":"Log Risk Score","config":{"baseId":"","fields":{"Name":"{{input.businessName}}","Website":"{{input.website}}","RiskLevel":"{{input.riskLevel}}","RiskScore":"{{input.riskScore}}"},"tableId":"Clients","operation":"create"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Records the assessment on the client record so onboarding decisions are auditable."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"if_high_risk","data":{"icon":"GitBranch","type":"if_else","label":"Is Risk High?","config":{"conditions":[{"field":"$json.isHighRisk","operator":"equals","value":true}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only high-risk signups interrupt anyone. Everything else onboards silently."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"slack_alert_compliance","data":{"icon":"MessageCircle","type":"slack_message","label":"Alert Compliance Team","config":{"channel":"#compliance-review","message":":rotating_light: High-risk signup: *{{input.businessName}}* ({{input.website}}) — risk score {{input.riskScore}}/100. Please review before onboarding."},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts a risky signup in front of compliance before onboarding continues."}},"type":"custom","position":{"x":2020,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"form_new_client","target":"http_domain_age_lookup"},{"id":"e2","source":"http_domain_age_lookup","target":"ai_risk_summary"},{"id":"e3","source":"ai_risk_summary","target":"js_risk_score"},{"id":"e4","source":"js_risk_score","target":"airtable_log_risk"},{"id":"e5","source":"airtable_log_risk","target":"if_high_risk"},{"id":"e6","source":"if_high_risk","target":"slack_alert_compliance","sourceHandle":"true"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 21,
    tags                 = ARRAY[$tpl$risk$tpl$,$tpl$fraud-prevention$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$,$tpl$onboarding$tpl$,$tpl$compliance$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$08179609-fc6f-44a2-a5ca-ddb9874a7c6b$tpl$;

-- Overdue Task Tracker
UPDATE templates SET
    name                 = $tpl$Overdue Task Tracker$tpl$,
    description          = $tpl$Requests shouldn't sit untouched until a client complains. This workflow checks open items every hour, flags anything past its expected turnaround, alerts the responsible person, and escalates to their manager once it's gone very overdue.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"schedule_hourly_check","data":{"icon":"Clock","type":"schedule","label":"Check Every 5 Minutes","config":{"cron":"*/5 * * * *","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs every 5 minutes, handling one overdue request per run so a backlog clears quickly."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_open_requests","data":{"icon":"Database","type":"airtable","label":"Read Open Requests","config":{"baseId":"","tableId":"Requests","operation":"read","filterByFormula":"AND({Status}!='Closed', OR({LastAlertedAt}='', DATETIME_DIFF(NOW(), {LastAlertedAt}, 'hours') >= 4))","maxRecords":1,"sort":[{"field":"OpenedAt","direction":"asc"}]},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Picks up one open request that is either unalerted or last alerted more than 4 hours ago — that window is what stops the same request pinging someone hourly forever."}},"type":"custom","position":{"x":420,"y":300}},{"id":"js_flag_overdue","data":{"icon":"Code","type":"javascript","label":"Select Overdue Request","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, isOverdue: false };\nconst f = rec.fields || {};\nconst HOUR = 3600000;\nconst hoursOpen = Math.round((Date.now() - new Date(f.OpenedAt).getTime()) / HOUR);\nconst slaHours = f.SlaHours || 24;\nreturn {\n  ...input,\n  recordId: rec.id,\n  title: f.Title || f.Name || \"Untitled request\",\n  hoursOpen,\n  slaHours,\n  isOverdue: hoursOpen > slaHours,\n  isVeryOverdue: hoursOpen > slaHours * 2,\n  ownerSlackChannel: f.OwnerSlackChannel || \"#operations\",\n  managerSlackChannel: f.ManagerSlackChannel || \"#operations-escalations\",\n  alertedAt: new Date().toISOString()\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Compares how long the request has been open against its SLA and works out whether it is overdue or very overdue. Owner and manager channels come from the request row."}},"type":"custom","position":{"x":740,"y":300}},{"id":"slack_alert_owner","data":{"icon":"MessageCircle","type":"slack_message","label":"Alert Responsible Person","config":{"channel":"{{input.ownerSlackChannel}}","message":":clock3: Request *{{input.title}}* is overdue ({{input.hoursOpen}}h open, SLA {{input.slaHours}}h). Please action it."},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Tells the person responsible, in their own channel, before the client notices."}},"type":"custom","position":{"x":1380,"y":205}},{"id":"if_very_overdue","data":{"icon":"GitBranch","type":"if_else","label":"Is It Very Overdue?","config":{"conditions":[{"field":"$json.isVeryOverdue","operator":"equals","value":true}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Separates 'late' from 'badly late'. Only the second one involves a manager."}},"type":"custom","position":{"x":1380,"y":395}},{"id":"slack_escalate_manager","data":{"icon":"MessageCircle","type":"slack_message","label":"Escalate to Manager","config":{"channel":"{{input.managerSlackChannel}}","message":":rotating_light: Escalation: *{{input.title}}* is very overdue ({{input.hoursOpen}}h open, SLA {{input.slaHours}}h) and still unresolved."},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Escalates when something has gone past twice its SLA and still nobody has acted."}},"type":"custom","position":{"x":1700,"y":205}},{"id":"airtable_mark_alerted","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Database","type":"airtable","label":"Record Alert Sent","category":"data","config":{"baseId":"","tableId":"Requests","operation":"update","recordId":"{{input.recordId}}","fields":{"LastAlertedAt":"{{input.alertedAt}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Stamps the alert time, which is what makes the 4-hour re-alert window work."}}},{"id":"if_isoverdue","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Anything Actually Overdue?","category":"logic","config":{"conditions":[{"field":"$json.isOverdue","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Most polls find nothing overdue. Without this the workflow posted a blank Slack alert every 5 minutes."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_hourly_check","target":"airtable_read_open_requests"},{"id":"e2","source":"airtable_read_open_requests","target":"js_flag_overdue"},{"id":"e3","source":"if_isoverdue","target":"slack_alert_owner","sourceHandle":"true"},{"id":"e4","source":"if_isoverdue","target":"if_very_overdue","sourceHandle":"true"},{"id":"e5","source":"if_very_overdue","target":"slack_escalate_manager","sourceHandle":"true"},{"id":"e_slack_alert_owner_airtable_mark_alerted","source":"slack_alert_owner","target":"airtable_mark_alerted"},{"id":"e_js_flag_overdue_if_isoverdue","source":"js_flag_overdue","target":"if_isoverdue"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 15,
    tags                 = ARRAY[$tpl$sla$tpl$,$tpl$slack$tpl$,$tpl$operations$tpl$,$tpl$monitoring$tpl$,$tpl$airtable$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$8431165d-7466-4579-8940-8b0724b28db2$tpl$;

