    edges                = $tpl$[{"id":"e_1_webhook_payment_failed_js_extract_payment","source":"webhook_payment_failed","target":"js_extract_payment"},{"id":"e_2_js_extract_payment_ai_recovery_message","source":"js_extract_payment","target":"ai_recovery_message"},{"id":"e_3_ai_recovery_message_gmail_payment_recovery","source":"ai_recovery_message","target":"gmail_payment_recovery"},{"id":"e_4_gmail_payment_recovery_if_high_value_payment","source":"gmail_payment_recovery","target":"if_high_value_payment"},{"id":"e_5_if_high_value_payment_slack_payment_followup","source":"if_high_value_payment","target":"slack_payment_followup","sourceHandle":"true"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 20,
    tags                 = ARRAY[$tpl$finance$tpl$,$tpl$billing$tpl$,$tpl$webhook$tpl$,$tpl$email$tpl$,$tpl$slack$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Sales & Lead Qualification Agent
UPDATE templates SET
    name                 = $tpl$Sales & Lead Qualification Agent$tpl$,
    description          = $tpl$Automated lead qualification agent that captures lead information, asks qualifying questions, scores leads, and routes qualified leads to CRM with meeting booking. Unqualified leads receive automated follow-up.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"webhook_lead_1","data":{"icon":"Webhook","type":"webhook","label":"Lead Webhook","config":{"method":"POST"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives leads from your website forms or ad landing pages."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_extract_lead","data":{"icon":"Code","type":"javascript","label":"Extract Lead Data","config":{"code":"return { name: input.name || input.full_name || 'Unknown', email: input.email || '', company: input.company || input.company_name || '', phone: input.phone || input.phone_number || '', source: input.source || 'web', message: input.message || input.notes || '', timestamp: new Date().toISOString() };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Normalises the different field names lead sources use into one shape."}},"type":"custom","position":{"x":420,"y":300}},{"id":"ai_score_lead","data":{"icon":"Brain","type":"openai_gpt","label":"Score Lead","config":{"model":"gpt-4o-mini","memory":3,"prompt":"Score this lead from 0-100 on fit and intent.\n\nLead:\n- Name: {{input.name}}\n- Company: {{input.company}}\n- Email: {{input.email}}\n- Phone: {{input.phone}}\n- Source: {{input.source}}\n- Message: {{input.message}}\n\nWeigh company signal, how specific and serious the message is, and how complete the contact details are. Return ONLY JSON: { \"score\": number (0-100), \"qualified\": boolean (score >= 60), \"reasoning\": string }.","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Scores fit and intent from the lead's own details. The lead data is interpolated into the prompt — without that the model would be scoring nothing."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_extract_score","data":{"icon":"Code","type":"javascript","label":"Extract Score","config":{"code":"try { const content = input.content || input.text || input.response || '{}'; const jsonMatch = content.match(/\\{[\\s\\S]*\\}/); if (jsonMatch) { const parsed = JSON.parse(jsonMatch[0]); return { score: parsed.score || 50, qualified: parsed.qualified !== undefined ? parsed.qualified : (parsed.score >= 60), reasoning: parsed.reasoning || 'No reasoning provided' }; } return { score: 50, qualified: false, reasoning: 'Could not parse score' }; } catch (e) { return { score: 50, qualified: false, reasoning: 'Error parsing score: ' + e.message }; }"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Extracts the score and qualified flag from the AI's JSON."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"if_qualified_check","data":{"icon":"GitBranch","type":"if_else","label":"Check Qualification","config":{"conditions":[{"field":"$json.qualified","operator":"equals","value":true}],"combineOperation":"AND"},"category":"logic","notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Splits leads worth a salesperson's time from ones that get nurtured. 60 is the threshold, set in the scoring prompt."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"db_create_crm","data":{"icon":"Zap","type":"hubspot","label":"Create HubSpot Contact","config":{"resource":"contact","operation":"create","properties":{"email":"{{input.email}}","firstname":"{{input.name}}","company":"{{input.company}}","phone":"{{input.phone}}","hs_lead_status":"QUALIFIED"}},"category":"crm","notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Creates the contact in HubSpot so a qualified lead lands in your real CRM pipeline, not in a side table nobody works from."}},"type":"custom","position":{"x":1700,"y":205}},{"id":"js_generate_booking","data":{"icon":"Code","type":"javascript","label":"Generate Booking Link","config":{"code":"// Set this to your own scheduling link when you set up the template.\nconst baseUrl = input.bookingBaseUrl || \"REPLACE_WITH_YOUR_BOOKING_LINK\";\nconst params = new URLSearchParams({ name: input.name || \"\", email: input.email || \"\", company: input.company || \"\" });\nreturn { ...input, bookingLink: baseUrl + \"?\" + params.toString(), email: input.email, name: input.name };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Builds a personalised booking link. Replace the placeholder URL with your own scheduling link."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"email_qualified","data":{"icon":"Mail","type":"google_gmail","label":"Send Booking Email","config":{"to":"{{input.email}}","body":"Hi {{input.name}},\\n\\nThank you for your interest! Based on your needs, we'd love to schedule a consultation with you.\\n\\nBook a meeting: {{input.bookingLink}}\\n\\nLooking forward to speaking with you!\\n\\nBest regards,\\nSales Team","subject":"Let's Schedule Your Consultation","operation":"send"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Invites a qualified lead to book while their interest is still fresh — the speed here is most of the value."}},"type":"custom","position":{"x":2340,"y":300}},{"id":"email_followup","data":{"icon":"Mail","type":"google_gmail","label":"Send Follow-up Email","config":{"to":"{{input.email}}","body":"Hi {{input.name}},\\n\\nThank you for reaching out! We've received your inquiry and will keep you updated with relevant information.\\n\\nIf you have any questions, feel free to reply to this email.\\n\\nBest regards,\\nTeam","subject":"Thank You for Your Interest","operation":"send"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Keeps unqualified leads warm rather than dropping them."}},"type":"custom","position":{"x":1700,"y":395}},{"id":"log_result","data":{"icon":"FileOutput","type":"log_output","label":"Log Result","config":{"level":"info","message":"Lead processed: {{input.name}} ({{input.email}}) - Score: {{input.score}}, Qualified: {{input.qualified}}"},"category":"utility","notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"Records every lead and its score, which is how you tune the threshold over time."}},"type":"custom","position":{"x":2660,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"webhook_lead_1","target":"js_extract_lead"},{"id":"e5","source":"ai_score_lead","target":"js_extract_score"},{"id":"e6","source":"js_extract_score","target":"if_qualified_check"},{"id":"e7","source":"if_qualified_check","target":"db_create_crm","sourceHandle":"true"},{"id":"e8","source":"if_qualified_check","target":"email_followup","sourceHandle":"false"},{"id":"e9","source":"db_create_crm","target":"js_generate_booking"},{"id":"e10","source":"js_generate_booking","target":"email_qualified"},{"id":"e11","source":"email_qualified","target":"log_result"},{"id":"e12","source":"email_followup","target":"log_result"},{"id":"e_js_extract_lead_ai_score_lead","source":"js_extract_lead","target":"ai_score_lead"}]$tpl$::jsonb,
    difficulty           = $tpl$Advanced$tpl$,
    estimated_setup_time = 12,
    tags                 = ARRAY[$tpl$sales$tpl$,$tpl$lead-qualification$tpl$,$tpl$crm$tpl$,$tpl$booking$tpl$,$tpl$scoring$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$ddd65341-f690-46f8-8436-3df14e283c28$tpl$;

-- Smart Alert Co-Pilot
UPDATE templates SET
    name                 = $tpl$Smart Alert Co-Pilot$tpl$,
    description          = $tpl$Move from 'checking on a schedule' to 'getting told the moment something's wrong.' An AI judgment layer watches your client records, pulls related context before deciding, and sends a targeted alert to the right person only when a change is actually worth interrupting someone for. (No instant Airtable-update trigger exists yet, so this polls every 10 minutes instead of firing immediately.)$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"schedule_poll_alerts","data":{"icon":"Clock","type":"schedule","label":"Poll for Record Changes","config":{"cron":"*/10 * * * *","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Polls every 10 minutes because there is no 'row changed' trigger. One record per run."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_all_records","data":{"icon":"Database","type":"airtable","label":"Read All Client Records","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"OR({AlertCheckedAt}='', IS_AFTER(LAST_MODIFIED_TIME(), {AlertCheckedAt}))","maxRecords":1},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Picks up one record modified since it was last examined."}},"type":"custom","position":{"x":420,"y":300}},{"id":"js_diff_for_alerts","data":{"icon":"Code","type":"javascript","label":"Select Changed Record","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasRecord: false };\nreturn {\n  ...input,\n  hasRecord: true,\n  recordId: rec.id,\n  changed: rec.fields || {},\n  checkedAt: new Date().toISOString()\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Prepares the changed record for the AI to judge."}},"type":"custom","position":{"x":740,"y":300}},{"id":"ai_agent_judge_alert","data":{"icon":"Bot","type":"ai_agent","label":"Judge Whether This Is Alert-Worthy","config":{"model":"gemini-3.5-flash","userInput":"Changed record(s): {{input.changed}}\nRelated context: {{input.records}}","temperature":0.3,"systemPrompt":"You are a compliance monitoring co-pilot. You are given a changed client record plus related context records. Decide whether this change is worth interrupting a person for right now (e.g. a readiness score dropped sharply, a document expired, a risk flag appeared) versus routine (e.g. a timestamp update, a minor note edit). Reply as JSON: {\"alertWorthy\": true/false, \"reason\": \"...\", \"severity\": \"low|medium|high\"}."},"category":"ai","notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"The judgment layer, and the reason this template exists: it decides whether a change is worth interrupting a person for, rather than alerting on everything."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"js_route_notification","data":{"icon":"Code","type":"javascript","label":"Decide Who to Notify","config":{"code":"// Set these two channels when you set up the template.\nconst complianceLeadChannel = input.complianceLeadChannel || \"#compliance-alerts\";\nconst accountManagerChannel = input.accountManagerChannel || \"#account-management\";\nconst recipientChannel = input.severity === \"high\" ? complianceLeadChannel : accountManagerChannel;\nreturn { ...input, recipientChannel };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Sends high-severity alerts to the compliance channel and everything else to the account-management channel. Set both channels here."}},"type":"custom","position":{"x":2660,"y":300}},{"id":"whatsapp_send_smart_alert","data":{"icon":"Hash","type":"slack_message","label":"Send Targeted Slack Alert","config":{"channel":"{{input.recipientChannel}}","message":":rotating_light: {{input.severity}} priority alert: {{input.reason}}"},"category":"output","notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Posts the alert to the one Slack channel that needs it."}},"type":"custom","position":{"x":2980,"y":300}},{"id":"js_parse_alert_decision","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Alert Decision","category":"data","config":{"code":"let decision = {};\ntry {\n  const text = input.response || input.text || input.content || \"{}\";\n  const m = text.match(/\\{[\\s\\S]*\\}/);\n  decision = m ? JSON.parse(m[0]) : {};\n} catch (e) { decision = {}; }\nreturn {\n  ...input,\n  alertWorthy: decision.alertWorthy === true,\n  reason: decision.reason || \"\",\n  severity: decision.severity || \"low\"\n};","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Extracts the verdict, reason and severity from the agent's reply."}}},{"id":"if_alert_worthy","type":"custom","position":{"x":2340,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Is This Worth Interrupting Someone?","category":"logic","config":{"conditions":[{"field":"$json.alertWorthy","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Enforces the agent's verdict. Without this node the workflow alerts on every change and becomes a noisier version of a dumb alert."}}},{"id":"airtable_mark_alert_checked","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Record Alert Check","category":"data","config":{"baseId":"","tableId":"Clients","operation":"update","recordId":"{{input.recordId}}","fields":{"AlertCheckedAt":"{{input.checkedAt}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Stamps the record as examined — deliberately BEFORE the gate below, so records judged not worth alerting are not re-judged and re-billed on every subsequent poll."}}},{"id":"if_hasrecord","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Any Record Changed?","category":"logic","config":{"conditions":[{"field":"$json.hasRecord","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Stops an empty poll from burning an AI call and sending a blank alert."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_poll_alerts","target":"airtable_read_all_records"},{"id":"e2","source":"airtable_read_all_records","target":"js_diff_for_alerts"},{"id":"e5","source":"js_parse_alert_decision","target":"airtable_mark_alert_checked"},{"id":"e6","source":"js_route_notification","target":"whatsapp_send_smart_alert"},{"id":"e_js_diff_for_alerts_ai_agent_judge_alert","source":"if_hasrecord","target":"ai_agent_judge_alert","sourceHandle":"true"},{"id":"e_ai_agent_judge_alert_js_parse_alert_decision","source":"ai_agent_judge_alert","target":"js_parse_alert_decision"},{"id":"e_if_alert_worthy_js_route_notification","source":"if_alert_worthy","target":"js_route_notification","sourceHandle":"true"},{"id":"e_airtable_mark_alert_checked_if_alert_worthy","source":"airtable_mark_alert_checked","target":"if_alert_worthy"},{"id":"e_js_diff_for_alerts_if_hasrecord","source":"js_diff_for_alerts","target":"if_hasrecord"}]$tpl$::jsonb,
    difficulty           = $tpl$Advanced$tpl$,
    estimated_setup_time = 21,
    tags                 = ARRAY[$tpl$ai-agent$tpl$,$tpl$alerts$tpl$,$tpl$monitoring$tpl$,$tpl$airtable$tpl$,$tpl$slack$tpl$,$tpl$co-pilot$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$53bc3b52-0655-4c4e-9cf0-36050463e603$tpl$;

-- Submission Package Builder
UPDATE templates SET
    name                 = $tpl$Submission Package Builder$tpl$,
    description          = $tpl$Once a client's readiness score clears the bar, this workflow automatically gathers the homepage/policy screenshots, live policy text, and already-uploaded documents a verification submission needs, and emails you all the pieces. Simplification: since this platform has no PDF-merge node, the pieces are delivered as individual links rather than one combined PDF.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"schedule_poll_ready","data":{"icon":"Clock","type":"schedule","label":"Poll for Ready Clients","config":{"cron":"*/15 * * * *","timezone":"UTC"},"category":"triggers","notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Polls for clients who have cleared the readiness bar. One client per run."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_read_ready_status","data":{"icon":"Database","type":"airtable","label":"Read Clients With Status = Ready","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"AND({Status}='Ready', {PackageSentAt}='')","maxRecords":1},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Picks up one ready client whose package has not been built yet."}},"type":"custom","position":{"x":420,"y":300}},{"id":"js_detect_newly_ready_status","data":{"icon":"Code","type":"javascript","label":"Select Ready Client","config":{"code":"const rec = (input.records || [])[0];\nif (!rec) return { ...input, hasClient: false };\nconst f = rec.fields || {};\nreturn {\n  ...input,\n  hasClient: true,\n  recordId: rec.id,\n  businessName: f.Name || \"\",\n  website: f.Website || \"\",\n  contactEmail: f.Email || \"\",\n  sentAt: new Date().toISOString()\n};"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Lifts the client's website, name and email to the top level for the steps below."}},"type":"custom","position":{"x":740,"y":300}},{"id":"http_screenshot_pages","data":{"icon":"Globe","type":"http_request","label":"Screenshot Homepage & Policy Pages","config":{"url":"https://api.screenshotone.com/take?url={{input.website}}&access_key=REPLACE_WITH_YOUR_SCREENSHOTONE_ACCESS_KEY","method":"GET","headers":{},"timeout":15000},"category":"http_api","notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Captures the homepage and policy pages as images, which verification submissions usually require as evidence. Needs your own screenshot API key — replace the placeholder."}},"type":"custom","position":{"x":1380,"y":205}},{"id":"http_fetch_policy_text","data":{"icon":"Globe","type":"http_request","label":"Fetch Privacy Policy / Terms Text","config":{"url":"{{input.website}}/privacy-policy","method":"GET","headers":{},"timeout":10000},"category":"http_api","notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Pulls the live privacy policy and terms text so the submission quotes what is actually published today."}},"type":"custom","position":{"x":1380,"y":395}},{"id":"drive_list_existing_docs","data":{"icon":"HardDrive","type":"google_drive","label":"List Client Documents in Drive","config":{"operation":"list"},"category":"data","notes":{"family":"Data","what":"Upload, download, list, or delete files in your Google Drive","overview":"List, upload, or download files in Google Drive. The Delete option is shown in the dropdown but is not implemented by the runtime executor â€” selecting it always fails.","tips":["Leave Folder ID empty to list/upload across the whole Drive, not just the root","File IDs are in the URL: /file/d/FILE_ID/view","Upload requires base64, plain text, or a data URL for File Data","Download returns dataBase64 for binary files (PDFs, images), or content for text/JSON files","Delete is not implemented â€” it always fails with \"Unsupported Google Drive operation: delete\""],"docsHref":"/docs/nodes/google_drive","why":"Collects the documents already on file so the package is complete rather than partial."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"gmail_send_package","data":{"icon":"Mail","type":"google_gmail","label":"Email the Submission Package","config":{"body":"Everything needed to submit {{input.businessName}} for verification:\n\nHomepage screenshot: {{input.screenshotUrl}}\nPrivacy Policy / Terms text: {{input.policyText}}\nExisting documents on file: {{input.files}}\n\nReview and submit whenever ready.","subject":"Submission package ready for {{input.businessName}}","operation":"send","recipientEmails":"{{input.contactEmail}}","recipientSource":"manual_entry"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Delivers every piece needed for the submission in one email. Pieces are sent as separate links because the platform has no PDF-merge step."}},"type":"custom","position":{"x":2660,"y":300}},{"id":"merge_package","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"GitMerge","type":"merge","label":"Combine Package Pieces","category":"logic","config":{},"notes":{"family":"Logic","what":"Combines results coming from two paths into one","overview":"Rejoins multiple workflow branches and combines their data into one payload for the next step.","tips":["Use overwrite for simple flat objects when duplicate keys can be replaced.","Use append when the next node should receive a list at {{$json.items}}.","Use deep_merge when branches add different nested details that should survive together.","Connect every branch that should rejoin into Merge, then connect Merge output to the final action."],"docsHref":"/docs/nodes/merge","why":"Joins the screenshot and policy-text branches. Without this join the email could only ever see one of the two."}}},{"id":"airtable_mark_package_sent","type":"custom","position":{"x":2340,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Package as Sent","category":"data","config":{"baseId":"","tableId":"Clients","operation":"update","recordId":"{{input.recordId}}","fields":{"PackageSentAt":"{{input.sentAt}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Stamps the client as packaged so the same package is not rebuilt and re-emailed every 15 minutes."}}},{"id":"if_hasclient","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Any Ready Client?","category":"logic","config":{"conditions":[{"field":"$json.hasClient","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Most polls find nothing. Without this the workflow screenshotted a blank URL and emailed an empty package every 15 minutes."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"schedule_poll_ready","target":"airtable_read_ready_status"},{"id":"e2","source":"airtable_read_ready_status","target":"js_detect_newly_ready_status"},{"id":"e3","source":"if_hasclient","target":"http_screenshot_pages","sourceHandle":"true"},{"id":"e4","source":"if_hasclient","target":"http_fetch_policy_text","sourceHandle":"true"},{"id":"e5","source":"http_screenshot_pages","target":"merge_package"},{"id":"e6","source":"http_fetch_policy_text","target":"merge_package"},{"id":"e7","source":"drive_list_existing_docs","target":"airtable_mark_package_sent"},{"id":"e_merge_package_drive","source":"merge_package","target":"drive_list_existing_docs"},{"id":"e_airtable_mark_package_sent_gmail_send_package","source":"airtable_mark_package_sent","target":"gmail_send_package"},{"id":"e_js_detect_newly_ready_status_if_hasclient","source":"js_detect_newly_ready_status","target":"if_hasclient"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 21,
    tags                 = ARRAY[$tpl$verification$tpl$,$tpl$compliance$tpl$,$tpl$google-drive$tpl$,$tpl$automation$tpl$,$tpl$documents$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$c0164dcb-4c8e-4be8-a806-4d00d2a969b7$tpl$;

-- Support Ticket Triage (NEW — split out of "Document Vault with Smart Search")
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000010$tpl$, $tpl$Support Ticket Triage$tpl$, $tpl$Classify new support requests, save the ticket, route urgent cases to Slack, and email the customer with next steps.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"form_support_request","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Support Request Form","category":"triggers","config":{"fields":[{"key":"customerEmail","type":"email","label":"Customer Email","required":true},{"key":"subject","type":"text","label":"Subject","required":true},{"key":"message","type":"textarea","label":"Message","required":true}],"formTitle":"Support Request","submitButtonText":"Send Request"},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects the customer issue in a structured form instead of an untracked inbox."}}},{"id":"ai_classify_ticket","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Classify Ticket","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Classify this support request. Subject: {{input.subject}}. Message: {{input.message}}. Return ONLY JSON: {\"priority\":\"low|normal|urgent\",\"category\":\"billing|technical|account|other\",\"summary\":\"short summary\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Turns the request into priority and category fields."}}},{"id":"js_parse_ticket","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Ticket Fields","category":"data","config":{"code":"let parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nreturn { ...input, priority: parsed.priority || \"normal\", category: parsed.category || \"other\", summary: parsed.summary || input.message || \"\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Creates stable fields for database storage and priority routing."}}},{"id":"postgres_create_ticket","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Box","type":"postgresql","label":"Create Support Ticket","category":"data","config":{"query":"INSERT INTO support_tickets (customer_email, subject, category, priority, summary, status, created_at) VALUES ('{{input.customerEmail}}', '{{input.subject}}', '{{input.category}}', '{{input.priority}}', '{{input.summary}}', 'open', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Creates a durable ticket instead of leaving support requests only in email or Slack."}}},{"id":"if_urgent_ticket","type":"custom","position":{"x":1380,"y":205},"data":{"icon":"GitBranch","type":"if_else","label":"Urgent Ticket?","category":"logic","config":{"conditions":[{"field":"$json.priority","operator":"equals","value":"urgent"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only urgent tickets interrupt the team immediately."}}},{"id":"slack_urgent_ticket","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Support Team","category":"output","config":{"channel":"#support-urgent","message":"Urgent support ticket: {{input.subject}}\n{{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts urgent requests in front of support staff fast."}}},{"id":"gmail_ticket_ack","type":"custom","position":{"x":1380,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Email Customer","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.customerEmail}}","subject":"We received your request","body":"We received your request about \"{{input.subject}}\". Priority: {{input.priority}}. Our team will follow up."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Confirms the ticket was received and sets customer expectations."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_support_request_ai_classify_ticket","source":"form_support_request","target":"ai_classify_ticket"},{"id":"e_2_ai_classify_ticket_js_parse_ticket","source":"ai_classify_ticket","target":"js_parse_ticket"},{"id":"e_3_js_parse_ticket_postgres_create_ticket","source":"js_parse_ticket","target":"postgres_create_ticket"},{"id":"e_4_postgres_create_ticket_if_urgent_ticket","source":"postgres_create_ticket","target":"if_urgent_ticket"},{"id":"e_5_if_urgent_ticket_slack_urgent_ticket","source":"if_urgent_ticket","target":"slack_urgent_ticket","sourceHandle":"true"},{"id":"e_6_postgres_create_ticket_gmail_ticket_ack","source":"postgres_create_ticket","target":"gmail_ticket_ack"}]$tpl$::jsonb, $tpl$Beginner$tpl$,
  18, ARRAY[$tpl$support$tpl$,$tpl$triage$tpl$,$tpl$ai$tpl$,$tpl$postgresql$tpl$,$tpl$email$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
