ert Support Team","category":"output","config":{"channel":"#support-urgent","message":"Urgent support ticket: {{input.subject}}\n{{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts urgent requests in front of support staff fast."}}},{"id":"gmail_ticket_ack","type":"custom","position":{"x":1380,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Email Customer","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.customerEmail}}","subject":"We received your request","body":"We received your request about \"{{input.subject}}\". Priority: {{input.priority}}. Our team will follow up."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Confirms the ticket was received and sets customer expectations."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_form_support_request_ai_classify_ticket","source":"form_support_request","target":"ai_classify_ticket"},{"id":"e_2_ai_classify_ticket_js_parse_ticket","source":"ai_classify_ticket","target":"js_parse_ticket"},{"id":"e_3_js_parse_ticket_postgres_create_ticket","source":"js_parse_ticket","target":"postgres_create_ticket"},{"id":"e_4_postgres_create_ticket_if_urgent_ticket","source":"postgres_create_ticket","target":"if_urgent_ticket"},{"id":"e_5_if_urgent_ticket_slack_urgent_ticket","source":"if_urgent_ticket","target":"slack_urgent_ticket","sourceHandle":"true"},{"id":"e_6_postgres_create_ticket_gmail_ticket_ack","source":"postgres_create_ticket","target":"gmail_ticket_ack"}]$tpl$::jsonb,
