-- Verification Co-Pilot Chat
UPDATE templates SET
    name                 = $tpl$Verification Co-Pilot Chat$tpl$,
    description          = $tpl$Answer 'what's the status of X?' without anyone manually digging through records. Ask in plain English over chat or Slack and an AI co-pilot pulls the live client record — and optionally a platform status API — to give a grounded, current answer, with no app-switching required.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"chat_trigger_copilot","data":{"icon":"MessageSquare","type":"chat_trigger","label":"Staff/Client Question","config":{},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Lets staff or clients ask about a client's status in plain English, from the chat tool they already use."}},"type":"custom","position":{"x":100,"y":300}},{"id":"js_parse_query","data":{"icon":"Code","type":"javascript","label":"Extract Client Name From Question","config":{"code":"const raw = (typeof input === 'string') ? input : (input && (input.message || input.query || input.text)) || '';\nconst match = raw.match(/for ([A-Z][\\w& ]+)/) || raw.match(/'([^']+)'/);\nconst clientName = match ? match[1].trim() : raw;\nreturn { ...(typeof input === \"object\" && input ? input : {}), clientName, originalQuestion: raw };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Pulls the client name out of a conversational question. The pattern matching is deliberately simple — adjust it to your naming conventions."}},"type":"custom","position":{"x":420,"y":300}},{"id":"airtable_lookup_client_record","data":{"icon":"Database","type":"airtable","label":"Query Live Client Record","config":{"baseId":"","tableId":"Clients","operation":"read","filterByFormula":"SEARCH(LOWER('{{input.clientName}}'), LOWER({Name}))","maxRecords":5},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Fetches the live record. Filtered by name so the agent receives the relevant client rather than your whole table."}},"type":"custom","position":{"x":740,"y":300}},{"id":"ai_agent_answer","data":{"icon":"Bot","type":"ai_agent","label":"Compose Grounded Answer","config":{"model":"gemini-3.5-flash","userInput":"Question: {{input.originalQuestion}}\nClient record: {{input.records}}\n\nWrite a clear, human answer to the question using only this data.","temperature":0.3,"systemPrompt":"You are the Verification Co-Pilot. You never guess — you only answer using the client record and status data given to you below. If the data does not cover the question, say so plainly and offer to escalate to a human."},"category":"ai","notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Answers only from the record it was handed, and says so when the data does not cover the question. That grounding is what makes the answer trustworthy."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"whatsapp_reply_copilot","data":{"icon":"Send","type":"chat_send","label":"Reply in Chat","config":{"message":"{{input.response}}"},"category":"output","notes":{"family":"Database","what":"Sends a reply in a chat conversation — works with a chat trigger to create a bot","overview":"","tips":[],"docsHref":null,"why":"Returns the answer in chat, so nobody has to open Airtable."}},"type":"custom","position":{"x":1380,"y":300}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"chat_trigger_copilot","target":"js_parse_query"},{"id":"e2","source":"js_parse_query","target":"airtable_lookup_client_record"},{"id":"e5","source":"ai_agent_answer","target":"whatsapp_reply_copilot"},{"id":"e_airtable_lookup_client_record_ai_agent_answer","source":"airtable_lookup_client_record","target":"ai_agent_answer"}]$tpl$::jsonb,
    difficulty           = $tpl$Advanced$tpl$,
    estimated_setup_time = 24,
    tags                 = ARRAY[$tpl$ai-agent$tpl$,$tpl$chatbot$tpl$,$tpl$chat$tpl$,$tpl$airtable$tpl$,$tpl$co-pilot$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$19c9665f-25c5-472f-8c0e-4ed82b6ba249$tpl$;

-- Verification Readiness Checker
UPDATE templates SET
    name                 = $tpl$Verification Readiness Checker$tpl$,
    description          = $tpl$Know whether your business will pass Meta or Google verification before you apply. This workflow scores your website and documents against the checks verifiers actually run — privacy policy, terms, matching business details — then emails you a fix list so you can pass on the first try.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"form_intake","data":{"icon":"FileText","type":"form","label":"Client Intake Form","config":{"fields":[{"key":"businessName","type":"text","label":"Business Name","required":true},{"key":"website","type":"url","label":"Website URL","required":true},{"key":"contactEmail","type":"email","label":"Contact Email","required":true},{"key":"gstDocument","type":"file","label":"GST Certificate","required":true},{"key":"panDocument","type":"file","label":"PAN Card","required":true},{"key":"bankStatement","type":"file","label":"Bank Statement","required":true}],"formTitle":"Business Verification Intake","successMessage":"Thanks! We are analyzing your business now.","formDescription":"Tell us about your business so we can check your verification readiness.","submitButtonText":"Check My Readiness"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects everything the readiness check needs in one pass — details and documents together, so the client is not chased twice."}},"type":"custom","position":{"x":100,"y":300}},{"id":"airtable_create_client","data":{"icon":"Database","type":"airtable","label":"Create Client Record","config":{"baseId":"","fields":{"Name":"{{input.businessName}}","Email":"{{input.contactEmail}}","Status":"New","Website":"{{input.website}}"},"tableId":"Clients","operation":"create"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Creates the client record up front, so the score written later attaches to a row that already exists."}},"type":"custom","position":{"x":420,"y":300}},{"id":"http_fetch_website","data":{"icon":"Globe","type":"http_request","label":"Fetch Website HTML","config":{"url":"{{input.website}}","method":"GET","headers":{},"timeout":10000},"category":"http_api","notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Fetches the client's live site so the AI can look for the pages verifiers check. If a site blocks automated requests this returns empty and the score will be misleadingly low — check the execution log before trusting a bad score."}},"type":"custom","position":{"x":740,"y":300}},{"id":"ai_analyze_readiness","data":{"icon":"Brain","type":"openai_gpt","label":"Analyze Readiness","config":{"model":"gpt-4o-mini","prompt":"You are a compliance analyst preparing a business for Meta/Google verification. Website HTML: {{input.body}}. Business name on file: {{input.businessName}}. Uploaded documents: GST {{input.gstDocument}}, PAN {{input.panDocument}}, bank statement {{input.bankStatement}}. Check for: a visible Privacy Policy page, a visible Terms & Conditions page, a business name and address that match across the website and the documents, and a working contact page. List every issue you find as one line starting with \"ISSUE:\". If everything looks correct, return \"NO ISSUES FOUND\".","temperature":0.3},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Checks the site and documents against what verifiers actually look for: privacy policy, terms, matching business details, working contact page. One 'ISSUE:' line per problem."}},"type":"custom","position":{"x":1060,"y":300}},{"id":"js_score","data":{"icon":"Code","type":"javascript","label":"Calculate Readiness Score","config":{"code":"const text = input.response || input.text || '';\nconst issues = text.split('\\n').map(l => l.trim()).filter(l => l.toUpperCase().startsWith('ISSUE:'));\nconst deductionPerIssue = 15;\nconst score = Math.max(0, 100 - issues.length * deductionPerIssue);\nreturn { ...input, score, issues, issueCount: issues.length };","timeout":5000},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the issue list into a 0-100 score. Each issue costs 15 points — change that here to make the score stricter."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"airtable_update_score","data":{"icon":"Database","type":"airtable","label":"Write Score to Record","config":{"baseId":"","fields":{"Score":"{{input.score}}","Issues":"{{input.issues}}","Status":"Scored"},"tableId":"Clients","recordId":"{{input.records.0.id}}","operation":"update"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Writes the score back onto the client record so it is on file for the next check."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"ai_fix_list","data":{"icon":"Brain","type":"openai_gpt","label":"Write Fix List","config":{"model":"gpt-4o-mini","prompt":"Based on these readiness issues: {{input.issues}}, write 2-3 short, plain-English fixes the client should make before applying for Meta/Google verification. Keep it friendly, specific, and actionable. No jargon.","temperature":0.5},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Converts the technical issues into two or three plain-English actions the client can actually carry out."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"gmail_send_results","data":{"icon":"Mail","type":"google_gmail","label":"Email Results","config":{"body":"Hi {{input.businessName}},\n\nYour verification readiness score is {{input.score}}/100.\n\nHere is what to fix before you apply:\n{{input.fixList}}\n\nWe will keep this record on file for your next check.","subject":"Your verification readiness score: {{input.score}}/100","operation":"send","recipientEmails":"{{input.contactEmail}}","recipientSource":"manual_entry"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the score and the fix list. This is the deliverable the client came for."}},"type":"custom","position":{"x":2660,"y":300}},{"id":"js_compose_results","type":"custom","position":{"x":2340,"y":300},"data":{"icon":"Code","type":"javascript","label":"Assemble Result Payload","category":"data","config":{"code":"const fixList = input.response || input.text || input.content || \"\";\nreturn {\n  ...input,\n  fixList,\n  score: input.score,\n  issueCount: input.issueCount,\n  businessName: input.businessName,\n  contactEmail: input.contactEmail\n};","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Assembles the score, fix list and contact details into one payload so the email has everything it needs."}}}]$tpl$::jsonb,
